{
  "name": "CopyWar: AI Model Validator",
  "description": "Recruit 100 synthetic marketing personas to validate and vote on ad copy generated by different AI models."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Persona {
  id: string;
  name: string;
  role: 'Copywriter' | 'Marketer' | 'Creative Director' | 'Growth Hacker';
  specialty: string;
  yearsExperience: number;
  bias: string; // e.g., "Prefers punchy, short copy", "Loves storytelling"
  avatarId: number;
}

export interface ExcelRow {
  Test: string;
  Prompt: string;
  'Writer (Agent Mode)': string;
  'Writer (Chat mode)': string;
  'GPT 5.2': string;
  'GS PeM': string;
  'Gemini': string;
}

export interface VoteResult {
  winner: string;
  counts: {
    'Writer (Agent Mode)': number;
    'Writer (Chat mode)': number;
    'GPT 5.2': number;
    'GS PeM': number;
    'Gemini': number;
  };
  reasoning: string;
  personaVotes?: { personaId: string; votedFor: string; reason: string }[]; // Optional detail
}

export interface ProcessedRow extends ExcelRow {
  id: string;
  status: 'pending' | 'analyzing' | 'completed';
  result?: VoteResult;
}

export type ModelKey = 'Writer (Agent Mode)' | 'Writer (Chat mode)' | 'GPT 5.2' | 'GS PeM' | 'Gemini';

export const MODELS: ModelKey[] = [
  'Writer (Agent Mode)',
  'Writer (Chat mode)',
  'GPT 5.2',
  'GS PeM',
  'Gemini'
];

export const MODEL_COLORS: Record<ModelKey, string> = {
  'Writer (Agent Mode)': '#8b5cf6', // Violet
  'Writer (Chat mode)': '#ec4899', // Pink
  'GPT 5.2': '#10b981', // Emerald
  'GS PeM': '#f59e0b', // Amber
  'Gemini': '#3b82f6', // Blue
};

import { GoogleGenAI, Type } from "@google/genai";
import { Persona, VoteResult, ModelKey, MODELS } from '../types';

const getAiClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY environment variable is not set.");
  }
  return new GoogleGenAI({ apiKey });
};

export const generatePersonas = async (): Promise<Persona[]> => {
  const ai = getAiClient();

  const prompt = `
    Create 100 synthetic user personas for a marketing validation study.
    They should be a mix of Copywriters (SEO, Direct Response, Brand) and Marketers (Growth, Product, Content).

    Return a JSON array where each object has:
    - id (string, unique)
    - name (string)
    - role (one of: 'Copywriter', 'Marketer', 'Creative Director', 'Growth Hacker')
    - specialty (string, e.g., 'B2B SaaS', 'Fashion', 'Email Marketing')
    - yearsExperience (number, 1-20)
    - bias (string, short description of what they look for in copy, e.g., 'Hates jargon', 'Loves emotional hooks')
    - avatarId (number, 1-100)
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              name: { type: Type.STRING },
              role: { type: Type.STRING },
              specialty: { type: Type.STRING },
              yearsExperience: { type: Type.INTEGER },
              bias: { type: Type.STRING },
              avatarId: { type: Type.INTEGER }
            }
          }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini");
    return JSON.parse(text) as Persona[];
  } catch (error) {
    console.error("Error generating personas:", error);
    // Fallback if API fails or limit reached, though unlikely with correct key
    return [];
  }
};

export const evaluateCopyRow = async (
  promptText: string,
  modelOutputs: Record<ModelKey, string>,
  personas: Persona[]
): Promise<VoteResult> => {
  const ai = getAiClient();

  // We send a summarized version of personas to save tokens if needed, 
  // but gemini-3-flash handles large context well. We will send the full list to ensure accuracy.

  const inputs = JSON.stringify(modelOutputs, null, 2);
  const personaContext = JSON.stringify(personas.map(p => ({
    id: p.id,
    role: p.role,
    bias: p.bias
  })));

  const analysisPrompt = `
    You are simulating a voting session with 100 marketing experts.

    THE TASK:
    Evaluate the following 5 ad/email copy variations generated by AI models based on the prompt provided.

    THE PROMPT:
    "${promptText}"

    THE CANDIDATES (Model Outputs):
    ${inputs}

    THE JURY (100 Personas):
    ${personaContext}

    INSTRUCTIONS:
    1. Act as EACH of the 100 personas.
    2. Decide which single model output each persona would vote for based on their specific role and bias.
    3. Tally the votes.
    4. Provide a reasoning summary for the winning model.

    Return a JSON object with:
    - winner: The name of the winning model key.
    - counts: An object mapping each model key to the integer number of votes (must sum to 100).
    - reasoning: A string summary explaining why the winner won, citing persona types.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: analysisPrompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
            type: Type.OBJECT,
            properties: {
                winner: { type: Type.STRING },
                counts: {
                    type: Type.OBJECT,
                    properties: {
                        'Writer (Agent Mode)': { type: Type.INTEGER },
                        'Writer (Chat mode)': { type: Type.INTEGER },
                        'GPT 5.2': { type: Type.INTEGER },
                        'GS PeM': { type: Type.INTEGER },
                        'Gemini': { type: Type.INTEGER },
                    }
                },
                reasoning: { type: Type.STRING }
            }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini for evaluation");
    const result = JSON.parse(text) as VoteResult;
    return result;

  } catch (error) {
    console.error("Error evaluating row:", error);
    // Return empty fallback
    return {
      winner: "Error",
      counts: {
        'Writer (Agent Mode)': 0,
        'Writer (Chat mode)': 0,
        'GPT 5.2': 0,
        'GS PeM': 0,
        'Gemini': 0
      },
      reasoning: "Failed to process this row due to an error."
    };
  }
};

import React, { useCallback } from 'react';
import { Upload } from 'lucide-react';
import * as XLSX from 'xlsx';
import { ExcelRow } from '../types';

interface FileUploadProps {
  onDataLoaded: (data: ExcelRow[]) => void;
}

export const FileUpload: React.FC<FileUploadProps> = ({ onDataLoaded }) => {
  const handleFileUpload = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const bstr = evt.target?.result;
      const wb = XLSX.read(bstr, { type: 'binary' });
      const wsname = wb.SheetNames[0];
      const ws = wb.Sheets[wsname];
      const data = XLSX.utils.sheet_to_json<ExcelRow>(ws);

      // Basic validation to ensure columns exist
      const validData = data.filter(row => row.Test && row.Prompt && row.Gemini); // Check a few key fields
      onDataLoaded(validData);
    };
    reader.readAsBinaryString(file);
  }, [onDataLoaded]);

  return (
    <div className="w-full max-w-2xl mx-auto p-8 border-2 border-dashed border-slate-600 rounded-xl bg-slate-800/50 hover:bg-slate-800 transition-colors cursor-pointer group text-center">
      <label htmlFor="file-upload" className="cursor-pointer flex flex-col items-center justify-center">
        <div className="p-4 bg-blue-500/10 rounded-full mb-4 group-hover:scale-110 transition-transform">
          <Upload className="w-8 h-8 text-blue-500" />
        </div>
        <h3 className="text-xl font-semibold text-slate-200 mb-2">Upload Data Sheet</h3>
        <p className="text-slate-400 mb-6">Support for .xlsx files containing model outputs</p>
        <div className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2 rounded-lg font-medium transition-colors">
          Select Excel File
        </div>
        <input 
          id="file-upload" 
          type="file" 
          accept=".xlsx, .xls, .csv" 
          className="hidden" 
          onChange={handleFileUpload}
        />
      </label>
    </div>
  );
};

import React from 'react';
import { Persona } from '../types';
import { Users, User, Zap } from 'lucide-react';

interface PersonaGridProps {
  personas: Persona[];
  isGenerating: boolean;
}

export const PersonaGrid: React.FC<PersonaGridProps> = ({ personas, isGenerating }) => {
  if (isGenerating) {
    return (
      <div className="w-full py-12 flex flex-col items-center justify-center text-slate-400 animate-pulse">
        <Users className="w-16 h-16 mb-4 text-slate-600" />
        <p className="text-lg">Recruiting 100 synthetic experts from the Gemini network...</p>
      </div>
    );
  }

  if (personas.length === 0) return null;

  // Group by role for stats
  const roleCounts = personas.reduce((acc, p) => {
    acc[p.role] = (acc[p.role] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  return (
    <div className="mt-8 bg-slate-800/50 rounded-xl border border-slate-700 p-6">
      <div className="flex items-center justify-between mb-6">
        <div>
            <h2 className="text-xl font-bold text-white flex items-center gap-2">
            <Users className="text-blue-400 w-5 h-5" />
            Recruited Panel ({personas.length})
            </h2>
            <p className="text-sm text-slate-400 mt-1">
                Synthetic Copywriters & Marketers powered by Gemini
            </p>
        </div>
        <div className="flex gap-4 text-xs">
            {Object.entries(roleCounts).map(([role, count]) => (
                <div key={role} className="bg-slate-900 px-3 py-1 rounded-full border border-slate-700 text-slate-300">
                    <span className="font-bold text-blue-400">{count}</span> {role}s
                </div>
            ))}
        </div>
      </div>

      <div className="grid grid-cols-5 sm:grid-cols-8 md:grid-cols-10 lg:grid-cols-20 gap-2 h-48 overflow-y-auto pr-2 custom-scrollbar">
        {personas.map((persona) => (
          <div 
            key={persona.id} 
            className="group relative bg-slate-700 hover:bg-blue-600 rounded-md p-2 flex flex-col items-center justify-center transition-all cursor-help"
          >
            <div className="w-6 h-6 rounded-full bg-slate-600 group-hover:bg-white/20 flex items-center justify-center text-[10px] font-bold text-slate-300 group-hover:text-white mb-1">
               {persona.name.charAt(0)}
            </div>
            {/* Tooltip */}
            <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 w-48 bg-slate-900 text-xs p-3 rounded-lg shadow-xl border border-slate-600 opacity-0 group-hover:opacity-100 pointer-events-none z-50 transition-opacity">
                <div className="font-bold text-blue-400 mb-1">{persona.name}</div>
                <div className="text-slate-300 mb-1">{persona.role} • {persona.yearsExperience}y exp</div>
                <div className="text-slate-400 italic">"{persona.bias}"</div>
            </div>
            <div className="h-1 w-full bg-slate-600 rounded-full overflow-hidden">
                 {/* Visual indicator of experience or something else could go here */}
                 <div className="h-full bg-blue-400" style={{ width: `${Math.min(persona.yearsExperience * 5, 100)}%` }}></div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

import React from 'react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { VoteResult, MODEL_COLORS, ModelKey, MODELS } from '../types';
import { Trophy } from 'lucide-react';

interface ResultsChartProps {
  result: VoteResult;
}

export const ResultsChart: React.FC<ResultsChartProps> = ({ result }) => {
  const data = MODELS.map(key => ({
    name: key.replace('Writer ', '').replace('Mode', ''), // Shorten names for chart
    fullName: key,
    votes: result.counts[key],
    fill: MODEL_COLORS[key]
  }));

  // Sort data descending
  const sortedData = [...data].sort((a, b) => b.votes - a.votes);
  const winner = sortedData[0];

  return (
    <div className="bg-slate-800 rounded-xl border border-slate-700 p-6 flex flex-col h-full">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-semibold text-white">Voting Distribution</h3>
        <div className="flex items-center gap-2 bg-yellow-500/10 px-3 py-1 rounded-full border border-yellow-500/20">
          <Trophy className="w-4 h-4 text-yellow-500" />
          <span className="text-sm font-bold text-yellow-500">Winner: {winner.fullName} ({winner.votes}%)</span>
        </div>
      </div>

      <div className="flex-1 w-full min-h-[250px]">
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={data} layout="vertical" margin={{ top: 5, right: 30, left: 40, bottom: 5 }}>
            <XAxis type="number" domain={[0, 100]} hide />
            <YAxis 
                type="category" 
                dataKey="name" 
                width={100} 
                tick={{ fill: '#94a3b8', fontSize: 12 }} 
                axisLine={false}
                tickLine={false}
            />
            <Tooltip 
                cursor={{ fill: 'transparent' }}
                contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155', color: '#f8fafc' }}
                itemStyle={{ color: '#f8fafc' }}
                formatter={(value: number) => [`${value} Votes`, 'Votes']}
            />
            <Bar dataKey="votes" radius={[0, 4, 4, 0]} barSize={32}>
              {data.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={entry.fill} />
              ))}
            </Bar>
          </BarChart>
        </ResponsiveContainer>
      </div>

      <div className="mt-4 pt-4 border-t border-slate-700">
        <h4 className="text-sm font-medium text-slate-400 mb-2">Panel Reasoning</h4>
        <p className="text-sm text-slate-300 leading-relaxed bg-slate-900/50 p-3 rounded-lg border border-slate-700/50">
            {result.reasoning}
        </p>
      </div>
    </div>
  );
};

import React, { useState, useCallback } from 'react';
import { FileUpload } from './components/FileUpload';
import { PersonaGrid } from './components/PersonaGrid';
import { ResultsChart } from './components/ResultsChart';
import { generatePersonas, evaluateCopyRow } from './services/geminiService';
import { ExcelRow, Persona, ProcessedRow, MODELS, MODEL_COLORS } from './types';
import { Brain, Play, CheckCircle2, ChevronRight, BarChart3, AlertCircle } from 'lucide-react';

export default function App() {
  const [personas, setPersonas] = useState<Persona[]>([]);
  const [dataRows, setDataRows] = useState<ProcessedRow[]>([]);
  const [isGeneratingPersonas, setIsGeneratingPersonas] = useState(false);
  const [selectedRowId, setSelectedRowId] = useState<string | null>(null);

  // App Steps
  const [hasRecruited, setHasRecruited] = useState(false);

  const handleDataLoaded = useCallback((rows: ExcelRow[]) => {
    // Transform into processed rows with unique IDs
    const processed = rows.map((row, idx) => ({
      ...row,
      id: `row-${idx}`,
      status: 'pending' as const
    }));
    setDataRows(processed);
    if (processed.length > 0) setSelectedRowId(processed[0].id);
  }, []);

  const handleRecruitPersonas = async () => {
    setIsGeneratingPersonas(true);
    const recruited = await generatePersonas();
    setPersonas(recruited);
    setIsGeneratingPersonas(false);
    setHasRecruited(true);
  };

  const handleRunEvaluation = async (rowId: string) => {
    const row = dataRows.find(r => r.id === rowId);
    if (!row) return;

    // Optimistic update
    setDataRows(prev => prev.map(r => r.id === rowId ? { ...r, status: 'analyzing' } : r));

    const modelOutputs = {
        'Writer (Agent Mode)': row['Writer (Agent Mode)'],
        'Writer (Chat mode)': row['Writer (Chat mode)'],
        'GPT 5.2': row['GPT 5.2'],
        'GS PeM': row['GS PeM'],
        'Gemini': row['Gemini']
    };

    const result = await evaluateCopyRow(row.Prompt, modelOutputs, personas);

    setDataRows(prev => prev.map(r => r.id === rowId ? { ...r, status: 'completed', result } : r));
  };

  const handleRunAll = async () => {
    // Run sequentially to avoid rate limits if any, or just parallel chunks
    // For demo, we do one by one or a few
    for (const row of dataRows) {
        if (row.status === 'completed') continue;
        await handleRunEvaluation(row.id);
    }
  };

  const selectedRow = dataRows.find(r => r.id === selectedRowId);

  return (
    <div className="min-h-screen bg-slate-900 text-slate-100 font-sans selection:bg-blue-500/30">

      {/* Header */}
      <header className="border-b border-slate-800 bg-slate-900/50 backdrop-blur sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg">
                <Brain className="w-5 h-5 text-white" />
            </div>
            <h1 className="text-xl font-bold tracking-tight">CopyWar <span className="text-slate-500 font-normal">| AI Validator</span></h1>
          </div>
          <div className="flex items-center gap-4">
             {personas.length > 0 && (
                 <div className="flex items-center gap-2 text-sm text-green-400 bg-green-400/10 px-3 py-1 rounded-full border border-green-400/20">
                    <CheckCircle2 className="w-4 h-4" />
                    <span>{personas.length} Experts Active</span>
                 </div>
             )}
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 py-8">

        {/* Step 1: Data Upload */}
        {dataRows.length === 0 && (
            <div className="mt-12 flex flex-col items-center animate-fade-in">
                <h2 className="text-3xl font-bold mb-4 text-center">Validate Your AI Copy at Scale</h2>
                <p className="text-slate-400 mb-12 text-center max-w-2xl text-lg">
                    Upload your Excel test results. We'll recruit 100 synthetic marketing experts to vote on the best performing copy for every test case.
                </p>
                <FileUpload onDataLoaded={handleDataLoaded} />
            </div>
        )}

        {/* Main Dashboard */}
        {dataRows.length > 0 && (
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

                {/* Left Sidebar: Test List */}
                <div className="lg:col-span-3 space-y-4 h-[calc(100vh-140px)] flex flex-col">
                    <div className="flex items-center justify-between mb-2">
                        <h3 className="font-semibold text-slate-300">Test Cases ({dataRows.length})</h3>
                        {hasRecruited && (
                             <button 
                                onClick={handleRunAll}
                                className="text-xs bg-blue-600 hover:bg-blue-500 text-white px-2 py-1 rounded transition-colors"
                             >
                                Run All
                             </button>
                        )}
                    </div>

                    <div className="flex-1 overflow-y-auto space-y-2 pr-2 custom-scrollbar">
                        {dataRows.map(row => (
                            <button
                                key={row.id}
                                onClick={() => setSelectedRowId(row.id)}
                                className={`w-full text-left p-3 rounded-lg border transition-all ${
                                    selectedRowId === row.id 
                                    ? 'bg-blue-600/10 border-blue-500 shadow-[0_0_15px_rgba(59,130,246,0.15)]' 
                                    : 'bg-slate-800 border-slate-700 hover:border-slate-500'
                                }`}
                            >
                                <div className="flex justify-between items-start mb-1">
                                    <span className={`text-xs font-mono px-1.5 py-0.5 rounded ${selectedRowId === row.id ? 'bg-blue-500/20 text-blue-300' : 'bg-slate-700 text-slate-400'}`}>
                                        {row.Test}
                                    </span>
                                    {row.status === 'completed' && <CheckCircle2 className="w-4 h-4 text-green-500" />}
                                    {row.status === 'analyzing' && <div className="w-4 h-4 border-2 border-blue-500 border-t-transparent rounded-full animate-spin" />}
                                </div>
                                <div className="text-sm text-slate-300 line-clamp-2">{row.Prompt}</div>
                            </button>
                        ))}
                    </div>
                </div>

                {/* Center/Right: Action & Analysis */}
                <div className="lg:col-span-9 flex flex-col gap-6">

                    {/* Persona Recruitment Section (Sticky if not recruited) */}
                    <div className="bg-slate-800 rounded-xl border border-slate-700 p-6 shadow-xl">
                        {!hasRecruited ? (
                            <div className="flex flex-col items-center justify-center py-6 text-center">
                                <h3 className="text-2xl font-bold text-white mb-2">Recruit Your Panel</h3>
                                <p className="text-slate-400 mb-6 max-w-lg">
                                    Before we can vote, we need to generate 100 diverse personas (Copywriters, Marketers, Growth Hackers) with unique biases.
                                </p>
                                <button 
                                    onClick={handleRecruitPersonas}
                                    disabled={isGeneratingPersonas}
                                    className="flex items-center gap-2 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed text-white px-8 py-3 rounded-xl font-bold text-lg transition-all shadow-lg hover:shadow-blue-500/20"
                                >
                                    {isGeneratingPersonas ? (
                                        <>
                                            <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                                            Recruiting Agents...
                                        </>
                                    ) : (
                                        <>
                                            <Play className="w-5 h-5 fill-current" />
                                            Start Recruitment
                                        </>
                                    )}
                                </button>
                                <PersonaGrid personas={personas} isGenerating={isGeneratingPersonas} />
                            </div>
                        ) : (
                             <PersonaGrid personas={personas} isGenerating={false} />
                        )}
                    </div>

                    {/* Analysis Section */}
                    {selectedRow && hasRecruited && (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-fade-in-up">

                            {/* Copy Comparison */}
                            <div className="bg-slate-800 rounded-xl border border-slate-700 p-6 flex flex-col h-[500px]">
                                <div className="flex items-center justify-between mb-4">
                                    <h3 className="text-lg font-semibold text-white">Ad Copy Candidates</h3>
                                    {selectedRow.status !== 'completed' && selectedRow.status !== 'analyzing' && (
                                        <button 
                                            onClick={() => handleRunEvaluation(selectedRow.id)}
                                            className="text-sm bg-green-600 hover:bg-green-500 text-white px-4 py-1.5 rounded-lg font-medium transition-colors flex items-center gap-2"
                                        >
                                            <Play className="w-3 h-3 fill-current" />
                                            Run Vote
                                        </button>
                                    )}
                                </div>
                                <div className="flex-1 overflow-y-auto custom-scrollbar space-y-4 pr-2">
                                    {MODELS.map(model => (
                                        <div key={model} className="bg-slate-900 rounded-lg p-4 border border-slate-700/50">
                                            <div className="flex items-center gap-2 mb-2">
                                                <div className="w-2 h-2 rounded-full" style={{ backgroundColor: MODEL_COLORS[model] }} />
                                                <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">{model}</span>
                                            </div>
                                            <p className="text-sm text-slate-300 whitespace-pre-wrap leading-relaxed">
                                                {selectedRow[model]}
                                            </p>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {/* Results */}
                            <div className="h-[500px]">
                                {selectedRow.status === 'completed' && selectedRow.result ? (
                                    <ResultsChart result={selectedRow.result} />
                                ) : selectedRow.status === 'analyzing' ? (
                                    <div className="h-full bg-slate-800 rounded-xl border border-slate-700 flex flex-col items-center justify-center text-center p-8">
