export const evaluateCopyRow = async (
  promptText: string,
  modelOutputs: Record<ModelKey, string>,
  personas: Persona[]
): Promise<VoteResult> => {
  const ai = getAiClient();

  // Optimization: Send only psychographic data.
  const personaContext = JSON.stringify(personas.map(p => ({
    role: p.role,
    bias: p.bias,
    specialty: p.specialty
  })));

  // PREPARE CANDIDATES WITH SAFE IDs
  // We use Model_A, Model_B etc to prevent JSON key errors with special chars/spaces
  const safeCandidates: Record<string, string> = {};
  let candidatesDescription = "";

  MODELS.forEach(key => {
    const id = MODEL_ID_MAP[key];
    const content = modelOutputs[key];
    safeCandidates[id] = content;
    candidatesDescription += `${id} (Original Name: "${key}"): \n${content}\n---\n`;
  });

  const analysisPrompt = `
    You are simulating a voting session with 100 marketing experts (Personas).

    THE TASK:
    Evaluate 5 ad/email copy variations based on the User Prompt.

    USER PROMPT:
    "${promptText}"

    CANDIDATES:
    ${candidatesDescription}

    THE JURY (100 Personas):
    ${personaContext}

    INSTRUCTIONS:
    1. Analyze the 100 personas collectively to determine the vote distribution.
    2. Tally the votes accurately using the IDs (Model_A, Model_B, etc).
    3. Group the voters into 3-4 meaningful segments based on voting patterns.
    4. Provide an overall summary.

    Return a JSON object with:
    - winner: The ID of the winning model (e.g. "Model_A").
    - counts: An object mapping each model ID to the vote count (must sum to 100).
    - reasoning: A concise summary explaining the overall win (use original model names in text).
    - segments: An array of segment analysis objects ({name, winner, reason}).
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: analysisPrompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
            type: Type.OBJECT,
            properties: {
                winner: { type: Type.STRING },
                counts: {
                    type: Type.OBJECT,
                    properties: {
                        'Model_A': { type: Type.INTEGER },
                        'Model_B': { type: Type.INTEGER },
                        'Model_C': { type: Type.INTEGER },
                        'Model_D': { type: Type.INTEGER },
                        'Model_E': { type: Type.INTEGER },
                    }
                },
                reasoning: { type: Type.STRING },
                segments: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            name: { type: Type.STRING },
                            winner: { type: Type.STRING, description: "The Model ID (e.g. Model_A)" },
                            reason: { type: Type.STRING }
                        }
                    }
                }
            }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini for evaluation");

    const rawResult = JSON.parse(text);

    // MAP BACK TO ORIGINAL KEYS
    // We reconstruct the VoteResult using the original ModelKey types

    const finalCounts = {
        'Writer (Agent Mode)': 0,
        'Writer (Chat mode)': 0,
        'GPT 5.2': 0,
        'GS PeM': 0,
        'Gemini': 0
    };

    // Safe mapping for counts
    if (rawResult.counts) {
        Object.keys(MODEL_ID_MAP).forEach((originalKey) => {
            const safeId = MODEL_ID_MAP[originalKey as ModelKey];
            const count = rawResult.counts[safeId];
            if (typeof count === 'number') {
                finalCounts[originalKey as ModelKey] = count;
            }
        });
    }

    // Safe mapping for winner
    let winnerKey = ID_TO_MODEL_MAP[rawResult.winner] as string;
    if (!winnerKey) {
        // Fallback: try to find max in counts if winner key is invalid
        let max = -1;
        let maxKey = 'Gemini';
        for (const [key, val] of Object.entries(finalCounts)) {
             if (val > max) {
                 max = val;
                 maxKey = key;
             }
        }
        winnerKey = maxKey;
    }

    // Safe mapping for segments
    const finalSegments = (rawResult.segments || []).map((seg: any) => ({
        name: seg.name || "Segment",
        winner: ID_TO_MODEL_MAP[seg.winner] || seg.winner || "Gemini", // Map back ID to Name
        reason: seg.reason || ""
    }));

    const result: VoteResult = {
        winner: winnerKey,
        counts: finalCounts,
        reasoning: rawResult.reasoning || "No reasoning provided.",
        segments: finalSegments
    };

    return result;

  } catch (error) {
    console.error("Error evaluating row:", error);
    return {
      winner: "Error",
      counts: {
        'Writer (Agent Mode)': 0,
        'Writer (Chat mode)': 0,
        'GPT 5.2': 0,
        'GS PeM': 0,
        'Gemini': 0
      },
      reasoning: "Failed to process this row due to an error.",
      segments: []
    };
  }
};

