export const evaluateCopyRow = async (
  promptText: string,
  modelOutputs: Record<ModelKey, string>,
  personas: Persona[]
): Promise<VoteResult> => {
  const ai = getAiClient();

  // Optimization: Send simplified persona data to save context
  const personaContext = JSON.stringify(personas.map((p, index) => ({
    index: index,
    role: p.role,
    bias: p.bias,
    specialty: p.specialty
  })));

  // PREPARE CANDIDATES WITH SAFE IDs
  const safeCandidates: Record<string, string> = {};
  let candidatesDescription = "";

  MODELS.forEach(key => {
    const id = MODEL_ID_MAP[key];
    const content = modelOutputs[key];
    safeCandidates[id] = content;
    candidatesDescription += `${id} (Original Name: "${key}"): \n${content}\n---\n`;
  });

  const analysisPrompt = `
    You are simulating a voting session with ${personas.length} unique marketing experts.

    THE TASK:
    For EACH of the ${personas.length} personas provided in the list, determine which of the 5 Copy Candidates they would vote for.
    The decision must be based on their specific Role, Bias, and Specialty.

    USER PROMPT:
    "${promptText}"

    CANDIDATES:
    ${candidatesDescription}

    THE JURY (Personas):
    ${personaContext}

    INSTRUCTIONS:
    1. Iterate through every single persona in the jury list.
    2. Select the ONE best model ID (Model_A, Model_B, etc) for that specific persona.
    3. Provide a CRISP, SHORT reason (max 12 words).

    Return a JSON Object containing an array "votes".
    Each item in "votes" must be: { "personaIndex": number, "modelId": string, "reason": string }
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: analysisPrompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
            type: Type.OBJECT,
            properties: {
                votes: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            personaIndex: { type: Type.INTEGER },
                            modelId: { type: Type.STRING },
                            reason: { type: Type.STRING }
                        }
                    }
                }
            }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini for evaluation");

    const rawResult = JSON.parse(text);
    const rawVotes = rawResult.votes || [];

    // --- CLIENT SIDE AGGREGATION ---
    // We strictly calculate counts based on the individual votes returned to ensure data consistency.

    const finalCounts = {
        'Writer (Agent Mode)': 0,
        'Writer (Chat mode)': 0,
        'GPT 5.2': 0,
        'GS PeM': 0,
        'Gemini': 0
    };

    const individualVotes: IndividualVote[] = [];

    // Process each vote
    rawVotes.forEach((v: any) => {
        const pIndex = v.personaIndex;
        const safeModelId = v.modelId;
        const reason = v.reason;

        // Map back to real model key
        let modelKey = ID_TO_MODEL_MAP[safeModelId] || 'Gemini';

        // Safety check if model key is valid, if not default to Gemini (should rarely happen with safe IDs)
        if (!MODELS.includes(modelKey)) {
            modelKey = 'Gemini';
        }

        // Increment count
        finalCounts[modelKey]++;

        // Get persona details
        const persona = personas[pIndex];
        if (persona) {
            individualVotes.push({
                personaId: persona.id,
                personaName: persona.name,
                personaRole: persona.role,
                vote: modelKey,
                comment: reason
            });
        }
    });

    // Determine Winner
    let winnerKey = 'Gemini';
    let maxVotes = -1;
    for (const [key, count] of Object.entries(finalCounts)) {
        if (count > maxVotes) {
            maxVotes = count;
            winnerKey = key;
        }
    }

    // Generate simple summary
    const reasoning = `${winnerKey} won with ${maxVotes} votes out of ${individualVotes.length}, favored primarily for its adherence to the persona constraints.`;

    const result: VoteResult = {
        winner: winnerKey,
        counts: finalCounts,
        reasoning: reasoning,
        votes: individualVotes,
        segments: [] // User requested "no complex logic", so we skip complex segmentation
    };

    return result;

  } catch (error) {
    console.error("Error evaluating row:", error);
    return {
      winner: "Error",
      counts: {
        'Writer (Agent Mode)': 0,
        'Writer (Chat mode)': 0,
        'GPT 5.2': 0,
        'GS PeM': 0,
        'Gemini': 0
      },
      reasoning: "Failed to process this row due to an error.",
      votes: [],
      segments: []
    };
  }
};

