export interface Persona {
  id: string;
  name: string;
  role: string;
  bias: string;
}

// Matches the Excel columns exactly
export interface ExcelRow {
  Test: string;
  Prompt: string;
  'Writer (Agent Mode)': string;
  'Writer (Chat mode)': string;
  'GPT 5.2': string;
  'GS PeM': string;
  'Gemini': string;
}

// The specific keys for the models
export type ModelKey = 'Writer (Agent Mode)' | 'Writer (Chat mode)' | 'GPT 5.2' | 'GS PeM' | 'Gemini';

export const MODELS: ModelKey[] = [
  'Writer (Agent Mode)',
  'Writer (Chat mode)',
  'GPT 5.2',
  'GS PeM',
  'Gemini'
];

export const MODEL_COLORS: Record<ModelKey, string> = {
  'Writer (Agent Mode)': '#8b5cf6', // Violet
  'Writer (Chat mode)': '#ec4899', // Pink
  'GPT 5.2': '#10b981', // Emerald
  'GS PeM': '#f59e0b', // Amber
  'Gemini': '#3b82f6', // Blue
};

export interface Vote {
  personaName: string;
  personaRole: string;
  votedFor: ModelKey;
  reason: string;
}

export interface AnalysisResult {
  winner: ModelKey;
  counts: Record<ModelKey, number>;
  votes: Vote[];
}

export interface ReportItem extends ExcelRow {
  id: string;
  status: 'idle' | 'running' | 'done';
  analysis?: AnalysisResult;
}

import { GoogleGenAI, Type } from "@google/genai";
import { Persona, AnalysisResult, ModelKey, MODELS, Vote } from '../types';
import { getStaticPersonas } from './staticData';

const getAiClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY not set");
  return new GoogleGenAI({ apiKey });
};

// 1. GENERATE PERSONAS
export const generatePersonas = async (useLiveAi: boolean = false): Promise<Persona[]> => {
  if (!useLiveAi) return getStaticPersonas(); // Fast path

  // If we really wanted live generation, we'd add it here, 
  // but for reliability/speed in this demo, we stick to the robust static list 
  // or a very simple generator. For now, returning static is safest for "Recruit 100".
  return getStaticPersonas();
};

// 2. RUN VOTING SESSION
export const runVotingSession = async (
  promptText: string,
  candidates: Record<ModelKey, string>,
  personas: Persona[]
): Promise<AnalysisResult> => {
  const ai = getAiClient();

  // Map models to simple IDs to avoid special character issues in JSON
  const ID_MAP: Record<string, ModelKey> = {
    'A': 'Writer (Agent Mode)',
    'B': 'Writer (Chat mode)',
    'C': 'GPT 5.2',
    'D': 'GS PeM',
    'E': 'Gemini'
  };

  const REVERSE_MAP: Record<ModelKey, string> = {
    'Writer (Agent Mode)': 'A',
    'Writer (Chat mode)': 'B',
    'GPT 5.2': 'C',
    'GS PeM': 'D',
    'Gemini': 'E'
  };

  // Construct the candidates text
  let candidateText = "";
  for (const [key, val] of Object.entries(candidates)) {
    candidateText += `MODEL ${REVERSE_MAP[key as ModelKey]}:\n${val}\n\n`;
  }

  // Construct persona summary (index based)
  const personaList = personas.map((p, i) => 
    `#${i} ${p.name} (${p.role}): ${p.bias}`
  ).join('\n');

  const systemInstruction = `
    You are simulating a voting panel of 100 specific marketing personas.
    Task: Read the User Prompt and the 5 Model Outputs (A, B, C, D, E).
    For EACH persona in the provided list, decide which model wrote the best copy for that specific persona's taste.
    Return strictly a JSON array of 100 votes.
  `;

  const userPrompt = `
    ORIGINAL USER PROMPT: "${promptText}"

    --- CANDIDATE TEXTS ---
    ${candidateText}

    --- THE JURY (100 Personas) ---
    ${personaList}

    INSTRUCTIONS:
    Return a JSON object with a single key "votes".
    "votes" must be an array of objects: { "personaIndex": number, "choice": "A" | "B" | "C" | "D" | "E", "reason": "Short comment" }
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            votes: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  personaIndex: { type: Type.INTEGER },
                  choice: { type: Type.STRING },
                  reason: { type: Type.STRING }
                }
              }
            }
          }
        }
      },
      contents: userPrompt
    });

    const json = JSON.parse(response.text || '{}');
    const rawVotes = json.votes || [];

    // Tally results client-side
    const counts: Record<ModelKey, number> = {
      'Writer (Agent Mode)': 0,
      'Writer (Chat mode)': 0,
      'GPT 5.2': 0,
      'GS PeM': 0,
      'Gemini': 0
    };

    const votes: Vote[] = [];

    rawVotes.forEach((v: any) => {
      const modelKey = ID_MAP[v.choice as string];
      if (modelKey && personas[v.personaIndex]) {
        counts[modelKey]++;
        votes.push({
          personaName: personas[v.personaIndex].name,
          personaRole: personas[v.personaIndex].role,
          votedFor: modelKey,
          reason: v.reason
        });
      }
    });

    // Find winner
    let winner: ModelKey = 'Gemini';
    let max = -1;
    for (const m of MODELS) {
      if (counts[m] > max) {
        max = counts[m];
        winner = m;
      }
    }

    return { winner, counts, votes };

  } catch (e) {
    console.error("Evaluation failed", e);
    // Return empty fallback
    return {
      winner: 'Gemini',
      counts: {
        'Writer (Agent Mode)': 0,
        'Writer (Chat mode)': 0,
        'GPT 5.2': 0,
        'GS PeM': 0,
        'Gemini': 0
      },
      votes: []
    };
  }
};

import React, { useState } from 'react';
