import { GoogleGenAI, Type, Schema, HarmCategory, HarmBlockThreshold } from "@google/genai";
import { Persona, AnalysisResult, ModelKey, MODELS, Vote } from '../types';
import { getStaticPersonas } from './staticData';

const getAiClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY not set");
  return new GoogleGenAI({ apiKey });
};

// Helper to strip markdown code blocks just in case
function cleanJson(text: string): string {
  if (!text) return "{}";
  let cleaned = text.trim();
  // Remove markdown json wrappers
  if (cleaned.startsWith("```json")) {
    cleaned = cleaned.replace(/^```json/, "").replace(/```$/, "");
  } else if (cleaned.startsWith("```")) {
    cleaned = cleaned.replace(/^```/, "").replace(/```$/, "");
  }
  return cleaned;
}

// 1. GENERATE PERSONAS
export const generatePersonas = async (useLiveAi: boolean = false): Promise<Persona[]> => {
  if (!useLiveAi) return getStaticPersonas();
  return getStaticPersonas();
};

// 2. RUN VOTING SESSION
export const runVotingSession = async (
  promptText: string,
  candidates: Record<ModelKey, string>,
  personas: Persona[]
): Promise<AnalysisResult> => {
  const ai = getAiClient();

  // Map models to simple IDs
  const ID_MAP: Record<string, ModelKey> = {
    'A': 'Writer (Agent Mode)',
    'B': 'Writer (Chat mode)',
    'C': 'GPT 5.2',
    'D': 'GS PeM',
    'E': 'Gemini'
  };

  const REVERSE_MAP: Record<ModelKey, string> = {
    'Writer (Agent Mode)': 'A',
    'Writer (Chat mode)': 'B',
    'GPT 5.2': 'C',
    'GS PeM': 'D',
    'Gemini': 'E'
  };

  let candidateText = "";
  for (const [key, val] of Object.entries(candidates)) {
    candidateText += `MODEL ${REVERSE_MAP[key as ModelKey]}:\n${val}\n\n`;
  }

  const personaList = personas.map((p, i) => 
    `#${i} ${p.name} (${p.role}): ${p.bias}`
  ).join('\n');

  const systemInstruction = `
    You are simulating a voting panel of 100 specific marketing personas.
    Task: Read the User Prompt and the 5 Model Outputs (A, B, C, D, E).

    1. Analyze the texts based on the personas' biases.
    2. Provide a 'summary' paragraph (max 50 words) explaining the voting trend, why the winner won, and any key differentiators.
    3. For EACH persona in the provided list, decide which model wrote the best copy for that specific persona's taste.

    Return strictly a JSON object containing the summary and the array of votes.
  `;

  const userPrompt = `
    ORIGINAL USER PROMPT: "${promptText}"

    --- CANDIDATE TEXTS ---
    ${candidateText}

    --- THE JURY (100 Personas) ---
    ${personaList}

    INSTRUCTIONS:
    Return a JSON object with keys: "summary" (string) and "votes" (array).
    "votes" must be an array of objects: { "personaIndex": number, "choice": "A" | "B" | "C" | "D" | "E", "reason": "Short comment" }
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: systemInstruction,
        // Add safety settings to prevent false positives on marketing copy
        safetySettings: [
          { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH },
          { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH },
          { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH },
          { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH },
        ],
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            votes: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  personaIndex: { type: Type.INTEGER },
                  choice: { type: Type.STRING },
                  reason: { type: Type.STRING }
                }
              }
            }
          }
        }
      },
      contents: userPrompt
    });

    if (!response.text) {
        throw new Error("Model returned empty response (possibly blocked).");
    }

    const jsonStr = cleanJson(response.text);
    const json = JSON.parse(jsonStr);

    const rawVotes = json.votes || [];
    const summary = json.summary || "No summary provided.";

    const counts: Record<ModelKey, number> = {
      'Writer (Agent Mode)': 0,
      'Writer (Chat mode)': 0,
      'GPT 5.2': 0,
      'GS PeM': 0,
      'Gemini': 0
    };

    const votes: Vote[] = [];

    rawVotes.forEach((v: any) => {
      // Robust Parsing: handle "Model A", "A.", "Choice A"
      let choiceChar = v.choice?.toString().toUpperCase().trim().charAt(0) || '';
      const choiceStr = v.choice?.toString().toUpperCase() || '';

      // If the string contains "MODEL A" or similar, try to extract the letter
      const match = choiceStr.match(/\b([ABCDE])\b/);
      if (match) {
        choiceChar = match[1];
      }

      const modelKey = ID_MAP[choiceChar];

      if (modelKey && personas[v.personaIndex]) {
        counts[modelKey]++;
        votes.push({
          personaName: personas[v.personaIndex].name,
          personaRole: personas[v.personaIndex].role,
          votedFor: modelKey,
          reason: v.reason
        });
      }
    });

    let winner: ModelKey = 'Gemini';
    let max = -1;
    for (const m of MODELS) {
      if (counts[m] > max) {
        max = counts[m];
        winner = m;
      }
    }

    return { winner, counts, votes, summary };

  } catch (e: any) {
    console.error("Evaluation failed", e);
    return {
      winner: 'Gemini',
      counts: {
        'Writer (Agent Mode)': 0,
        'Writer (Chat mode)': 0,
        'GPT 5.2': 0,
        'GS PeM': 0,
        'Gemini': 0
      },
      votes: [],
      // Return the specific error message to the UI
      summary: `Analysis failed: ${e.message || "Unknown error"}`
    };
  }
};

import React, { useCallback, useState } from 'react';
import { Upload, AlertCircle, FileSpreadsheet } from 'lucide-react';
import * as XLSX from 'xlsx';
import { ExcelRow } from '../types';

interface FileUploadProps {
  onDataLoaded: (data: ExcelRow[]) => void;
}

export const FileUpload: React.FC<FileUploadProps> = ({ onDataLoaded }) => {
  const [error, setError] = useState<string | null>(null);

  const handleFileUpload = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    setError(null);
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];
        const data = XLSX.utils.sheet_to_json<any>(ws);

        // Basic validation: Check if we have data
        if (!data || data.length === 0) {
           setError("The uploaded file appears to be empty.");
           return;
        }

        // Check for essential columns in the first row
        const firstRow = data[0];
        if (!firstRow || !('Test' in firstRow) || !('Prompt' in firstRow)) {
            setError("Missing required columns. Please ensure your Excel file has headers 'Test' and 'Prompt'.");
            return;
        }

        // Filter valid rows
        const validData = data.filter((row: any) => row.Test && row.Prompt) as ExcelRow[];

        if (validData.length === 0) {
            setError("No valid rows found. Please check your data formatting.");
            return;
        }

        onDataLoaded(validData);
      } catch (err) {
        console.error(err);
        setError("Failed to parse the Excel file. Please try again.");
      }
    };
    reader.readAsBinaryString(file);
  }, [onDataLoaded]);

  return (
    <div className="w-full max-w-2xl mx-auto">
      <div className={`p-8 border-2 border-dashed rounded-xl transition-all cursor-pointer group text-center relative overflow-hidden ${error ? 'border-red-500/50 bg-red-500/5' : 'border-slate-600 bg-slate-800/50 hover:bg-slate-800'}`}>
        <label htmlFor="file-upload" className="cursor-pointer flex flex-col items-center justify-center relative z-10">
          <div className={`p-4 rounded-full mb-4 transition-transform group-hover:scale-110 ${error ? 'bg-red-500/10' : 'bg-blue-500/10'}`}>
            {error ? <AlertCircle className="w-8 h-8 text-red-500" /> : <Upload className="w-8 h-8 text-blue-500" />}
          </div>

          <h3 className="text-xl font-semibold text-slate-200 mb-2">
            {error ? "Upload Failed" : "Upload Data Sheet"}
          </h3>

          <p className="text-slate-400 mb-6 max-w-md mx-auto">
            {error || "Support for .xlsx files. Must contain columns: 'Test', 'Prompt', and model output columns."}
          </p>

          <div className={`px-6 py-2 rounded-lg font-medium transition-colors ${error ? 'bg-red-600 hover:bg-red-500 text-white' : 'bg-blue-600 hover:bg-blue-500 text-white'}`}>
            {error ? "Try Again" : "Select Excel File"}
          </div>

          <input 
            id="file-upload" 
            type="file" 
            accept=".xlsx, .xls, .csv" 
            className="hidden" 
            onChange={handleFileUpload}
            onClick={(e) => (e.currentTarget.value = '')} // Allow re-selecting same file
          />
        </label>
      </div>

      {/* Sample Data Format Hint */}
      {!error && (
        <div className="mt-6 flex items-start gap-3 text-xs text-slate-500 bg-slate-900/50 p-4 rounded-lg border border-slate-800">
           <FileSpreadsheet className="w-4 h-4 mt-0.5 shrink-0" />
           <div>
              <span className="font-semibold block mb-1">Required Excel Format:</span>
              <p>Columns: <code className="bg-slate-800 px-1 rounded">Test</code>, <code className="bg-slate-800 px-1 rounded">Prompt</code>, plus any model columns (e.g. <code className="bg-slate-800 px-1 rounded">Gemini</code>, <code className="bg-slate-800 px-1 rounded">GPT 5.2</code>).</p>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { FileUpload } from './components/FileUpload';
import { TestReportCard } from './components/TestReportCard';
import { PersonaGrid } from './components/PersonaGrid';
import { PdfReport } from './components/PdfReport';
import { generatePersonas, runVotingSession } from './services/geminiService';
import { ExcelRow, Persona, ReportItem, MODELS, ProcessedRow } from './types';
import { Brain, Users, Play, Loader2, Download, Zap, RefreshCw } from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

export default function App() {
  const [step, setStep] = useState<'upload' | 'recruit' | 'report'>('upload');
  const [items, setItems] = useState<ReportItem[]>([]);
  const [personas, setPersonas] = useState<Persona[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isRecruiting, setIsRecruiting] = useState(false);
  const pdfReportRef = useRef<HTMLDivElement>(null);
  const reportContainerRef = useRef<HTMLDivElement>(null);

  // 1. Upload Handler
  const handleDataLoaded = (data: ExcelRow[]) => {
    const reportItems: ReportItem[] = data.map((row, i) => ({
      ...row,
      id: `test-${i}`,
      status: 'idle'
    }));
    setItems(reportItems);
    setStep('recruit');
  };

  // 2. Recruit Handler
  const handleRecruit = async () => {
    setIsRecruiting(true);
    // Simulate a slight delay to feel like "generating"
    await new Promise(r => setTimeout(r, 800));
    const p = await generatePersonas(false); // Static 100
    setPersonas(p);
    setIsRecruiting(false);
    setStep('report');
  };

  // 3. Run All Handler
  const handleRunAll = async () => {
    setIsProcessing(true);

    // Find all pending items
    const pendingIndices = items.map((item, index) => item.status !== 'done' ? index : -1).filter(i => i !== -1);

    // Process in parallel batches of 2 (Safer for rate limits with large contexts)
    const BATCH_SIZE = 2;

    for (let i = 0; i < pendingIndices.length; i += BATCH_SIZE) {
        const batchIndices = pendingIndices.slice(i, i + BATCH_SIZE);

        // 1. Mark this batch as running in UI
        setItems(prev => {
            const next = [...prev];
            batchIndices.forEach(idx => {
                next[idx] = { ...next[idx], status: 'running' };
            });
            return next;
        });

        // 2. Execute parallel requests
        await Promise.all(batchIndices.map(async (index) => {
            const item = items[index];
            const modelOutputs = {
                'Writer (Agent Mode)': item['Writer (Agent Mode)'],
                'Writer (Chat mode)': item['Writer (Chat mode)'],
                'GPT 5.2': item['GPT 5.2'],
                'GS PeM': item['GS PeM'],
                'Gemini': item['Gemini']
            };

            try {
                const analysis = await runVotingSession(item.Prompt, modelOutputs, personas);

                // Update specific item upon completion
                setItems(prev => {
                    const next = [...prev];
                    next[index] = { ...next[index], status: 'done', analysis };
                    return next;
                });
            } catch (error) {
                console.error(`Error processing item ${index}`, error);
                // Reset status to idle if failed so user can retry
                setItems(prev => {
                    const next = [...prev];
                    next[index] = { ...next[index], status: 'idle' };
                    return next;
                });
            }
        }));

        // Small delay between batches to be nice to the API
        if (i + BATCH_SIZE < pendingIndices.length) {
            await new Promise(resolve => setTimeout(resolve, 1000));
        }
    }

    setIsProcessing(false);
  };

  const handleExportPDF = async () => {
    // We use the separate hidden PdfReport ref for high quality, detailed exports
    if (!pdfReportRef.current) return;

    try {
        const element = pdfReportRef.current;
        const canvas = await html2canvas(element, { 
            scale: 2, 
            backgroundColor: '#ffffff',
            windowWidth: 800
        });

        const imgData = canvas.toDataURL('image/png');
        const pdf = new jsPDF('p', 'mm', 'a4');
        const pdfWidth = pdf.internal.pageSize.getWidth();
        const pdfHeight = pdf.internal.pageSize.getHeight();
        const imgWidth = canvas.width;
        const imgHeight = canvas.height;
        const ratio = pdfWidth / imgWidth;
        const finalHeight = imgHeight * ratio;

        let heightLeft = finalHeight;
        let position = 0;

        pdf.addImage(imgData, 'PNG', 0, position, pdfWidth, finalHeight);
        heightLeft -= pdfHeight;

        while (heightLeft >= 0) {
          position = heightLeft - finalHeight;
          pdf.addPage();
          pdf.addImage(imgData, 'PNG', 0, position, pdfWidth, finalHeight);
          heightLeft -= pdfHeight;
        }
        pdf.save('CopyCritic_Report.pdf');
    } catch (e) {
        console.error(e);
        alert("Export failed");
    }
  };

  const completedCount = items.filter(i => i.status === 'done').length;

  // Transform ReportItems to ProcessedRows for the PDF component
  const processedRows: ProcessedRow[] = items.map(item => ({
      ...item,
      id: item.id,
      status: item.status === 'done' ? 'completed' : item.status === 'idle' ? 'pending' : 'failed',
      result: item.analysis ? {
          winner: item.analysis.winner,
          counts: item.analysis.counts,
          votes: item.analysis.votes,
          reasoning: item.analysis.summary
      } : undefined
  }));

  return (
    <div className="min-h-screen bg-slate-900 text-slate-100 font-sans pb-20">

      {/* Hidden PDF Render Target */}
      <PdfReport rows={processedRows} reportRef={pdfReportRef} />

      {/* Header */}
      <header className="border-b border-slate-800 bg-slate-900/90 backdrop-blur sticky top-0 z-50">
        <div className="max-w-4xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2 font-bold text-xl">
            <Brain className="text-blue-500" />
            CopyCritic
            <span className="text-[10px] font-normal bg-slate-800 text-slate-400 px-2 py-0.5 rounded-full border border-slate-700">v1.0.0</span>
          </div>
          <div className="text-sm text-slate-500">
             {personas.length > 0 ? `${personas.length} Personas Active` : ''}
          </div>
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-6 py-10">

        {/* STEP 1: UPLOAD */}
        {step === 'upload' && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            <h1 className="text-3xl font-bold text-center mb-4">Upload Validation Data</h1>
            <p className="text-center text-slate-400 mb-10">Upload your Excel sheet containing tests and model outputs.</p>
            <FileUpload onDataLoaded={handleDataLoaded} />
          </div>
        )}

        {/* STEP 2: RECRUIT */}
        {step === 'recruit' && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 text-center py-10">
            <div className="inline-flex p-6 bg-blue-500/10 rounded-full mb-6">
              <Users className="w-12 h-12 text-blue-500" />
