                            )}
                        </div>
                      ))}
                    </div>
                </>
            )}

          </div>
        )}

      </main>
    </div>
  );
}

import { GoogleGenAI, Type, Schema, HarmCategory, HarmBlockThreshold } from "@google/genai";
import { Persona, AnalysisResult, ModelKey, MODELS, Vote } from '../types';
import { getStaticPersonas } from './staticData';

const getAiClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY not set");
  return new GoogleGenAI({ apiKey });
};

// Helper for timeout
const timeoutPromise = (ms: number) => new Promise((_, reject) => 
    setTimeout(() => reject(new Error(`Request timed out after ${ms/1000} seconds`)), ms)
);

// Helper to strip markdown code blocks just in case
function cleanJson(text: string): string {
  if (!text) return "{}";
  let cleaned = text.trim();
  // Remove markdown json wrappers
  if (cleaned.startsWith("```json")) {
    cleaned = cleaned.replace(/^```json/, "").replace(/```$/, "");
  } else if (cleaned.startsWith("```")) {
    cleaned = cleaned.replace(/^```/, "").replace(/```$/, "");
  }
  return cleaned;
}

// 1. GENERATE PERSONAS
export const generatePersonas = async (useLiveAi: boolean = false): Promise<Persona[]> => {
  if (!useLiveAi) return getStaticPersonas();
  return getStaticPersonas();
};

// 2. RUN VOTING SESSION
export const runVotingSession = async (
  promptText: string,
  candidates: Record<ModelKey, string>,
  personas: Persona[]
): Promise<AnalysisResult> => {
  const ai = getAiClient();

  // Map models to simple IDs
  const ID_MAP: Record<string, ModelKey> = {
    'A': 'Writer (Agent Mode)',
    'B': 'Writer (Chat mode)',
    'C': 'GPT 5.2',
    'D': 'GS PeM',
    'E': 'Gemini'
  };

  const REVERSE_MAP: Record<ModelKey, string> = {
    'Writer (Agent Mode)': 'A',
    'Writer (Chat mode)': 'B',
    'GPT 5.2': 'C',
    'GS PeM': 'D',
    'Gemini': 'E'
  };

  let candidateText = "";
  for (const [key, val] of Object.entries(candidates)) {
    // Handle undefined/null values gracefully
    const safeVal = val || "[No content generated]";
    candidateText += `MODEL ${REVERSE_MAP[key as ModelKey]}:\n${safeVal}\n\n`;
  }

  // --- BATCHING STRATEGY ---
  // We process personas in batches of 25. 
  // Generating 100 outputs in one go takes too long (token generation latency).
  // 4 parallel requests of 25 outputs is ~4x faster in wall-clock time.
  const BATCH_SIZE = 25;
  const personaBatches = [];
  for (let i = 0; i < personas.length; i += BATCH_SIZE) {
    personaBatches.push(personas.slice(i, i + BATCH_SIZE));
  }

  try {
    const batchPromises = personaBatches.map(async (batchPersonas, batchIndex) => {
        const globalStartIndex = batchIndex * BATCH_SIZE;

        // Re-index locally for the model (0...24) to avoid confusion in the prompt
        const personaList = batchPersonas.map((p, i) => 
            `#${i} ${p.name} (${p.role}): ${p.bias}`
        ).join('\n');

        const systemInstruction = `
            You are simulating a voting panel of specific marketing personas.
            Task: Read the User Prompt and the 5 Model Outputs (A, B, C, D, E).

            1. Analyze the texts based on the personas' biases.
            2. For EACH persona in the provided list (from #0 to #${batchPersonas.length - 1}), decide which model wrote the best copy.
            3. Provide a brief 'summary' of the consensus for this specific group.

            IMPORTANT: 
            - Keep "reason" very brief (max 10 words).
            - Return strictly a JSON object.
        `;

        const userPrompt = `
            ORIGINAL USER PROMPT: "${promptText}"

            --- CANDIDATE TEXTS ---
            ${candidateText}

            --- THE JURY (Subset ${batchIndex + 1}) ---
            ${personaList}

            INSTRUCTIONS:
            Return a JSON object with keys: "summary" (string) and "votes" (array).
            "votes" must be an array of objects: { "personaIndex": number, "choice": "A" | "B" | "C" | "D" | "E", "reason": "Short comment (<10 words)" }
            (personaIndex should correspond to the list above, starting at 0)
        `;

        const response: any = await Promise.race([
            ai.models.generateContent({
              model: 'gemini-3-flash-preview',
              config: {
                systemInstruction: systemInstruction,
                safetySettings: [
                  { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH },
                  { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH },
                  { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH },
                  { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH },
                ],
                responseMimeType: 'application/json',
                responseSchema: {
                  type: Type.OBJECT,
                  properties: {
                    summary: { type: Type.STRING },
                    votes: {
                      type: Type.ARRAY,
                      items: {
                        type: Type.OBJECT,
                        properties: {
                          personaIndex: { type: Type.INTEGER },
                          choice: { type: Type.STRING },
                          reason: { type: Type.STRING }
                        }
                      }
                    }
                  }
                }
              },
              contents: userPrompt
            }),
            timeoutPromise(60000) // 60s timeout per batch is generous (usually takes 5-10s)
        ]);

        if (!response.text) throw new Error("Empty response");

        const json = JSON.parse(cleanJson(response.text));

        // Map local batch indices (0-24) back to global persona indices (e.g., 25-49)
        const mappedVotes = (json.votes || []).map((v: any) => ({
            ...v,
            personaIndex: v.personaIndex + globalStartIndex,
            // Fallback for missing/bad data
            choice: v.choice || 'E',
            reason: v.reason || 'No reason provided'
        }));

        return {
            votes: mappedVotes,
            summary: json.summary || ""
        };
    });

    // Run all batches in parallel
    const results = await Promise.all(batchPromises);

    // --- AGGREGATION ---
    const allVotes: any[] = results.flatMap(r => r.votes);

    // We use the summary from the first batch as the representative text
    // (Or we could concatenate them, but one is usually enough for the "consensus" feel)
    const summary = results[0]?.summary || "Analysis completed successfully.";

    const counts: Record<ModelKey, number> = {
      'Writer (Agent Mode)': 0,
      'Writer (Chat mode)': 0,
      'GPT 5.2': 0,
      'GS PeM': 0,
      'Gemini': 0
    };

    const finalVotes: Vote[] = [];

    allVotes.forEach((v: any) => {
      // Robust Parsing
      let choiceChar = v.choice?.toString().toUpperCase().trim().charAt(0) || '';
      const choiceStr = v.choice?.toString().toUpperCase() || '';

      const match = choiceStr.match(/\b([ABCDE])\b/);
      if (match) choiceChar = match[1];

      const modelKey = ID_MAP[choiceChar];

      // Ensure the persona exists (bounds check)
      if (modelKey && personas[v.personaIndex]) {
        counts[modelKey]++;
        finalVotes.push({
          personaName: personas[v.personaIndex].name,
          personaRole: personas[v.personaIndex].role,
          votedFor: modelKey,
          reason: v.reason
        });
      }
    });

    let winner: ModelKey = 'Gemini';
    let max = -1;
    for (const m of MODELS) {
      if (counts[m] > max) {
        max = counts[m];
        winner = m;
      }
    }

    return { winner, counts, votes: finalVotes, summary };

  } catch (e: any) {
    console.error("Evaluation failed", e);
    throw new Error(e.message || "Error during voting session");
  }
};

import React, { useState, useRef } from 'react';
import { FileUpload } from './components/FileUpload';
import { TestReportCard } from './components/TestReportCard';
import { PersonaGrid } from './components/PersonaGrid';
import { PdfReport } from './components/PdfReport';
import { generatePersonas, runVotingSession } from './services/geminiService';
import { ExcelRow, Persona, ReportItem, MODELS, ProcessedRow } from './types';
import { Brain, Users, Play, Loader2, Download, Zap, RefreshCw, AlertTriangle } from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

export default function App() {
  const [step, setStep] = useState<'upload' | 'recruit' | 'report'>('upload');
  const [items, setItems] = useState<ReportItem[]>([]);
  const [personas, setPersonas] = useState<Persona[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isRecruiting, setIsRecruiting] = useState(false);
  const pdfReportRef = useRef<HTMLDivElement>(null);
  const reportContainerRef = useRef<HTMLDivElement>(null);

  // 1. Upload Handler
  const handleDataLoaded = (data: ExcelRow[]) => {
    const reportItems: ReportItem[] = data.map((row, i) => ({
      ...row,
      id: `test-${i}`,
      status: 'idle'
    }));
    setItems(reportItems);
    setStep('recruit');
  };

  // 2. Recruit Handler
  const handleRecruit = async () => {
    setIsRecruiting(true);
    // Simulate a slight delay to feel like "generating"
    await new Promise(r => setTimeout(r, 800));
    const p = await generatePersonas(false); // Static 100
    setPersonas(p);
    setIsRecruiting(false);
    setStep('report');
  };

  // 3. Run All Handler
  const handleRunAll = async () => {
    setIsProcessing(true);

    // Find all pending items (including errors)
    const pendingIndices = items.map((item, index) => item.status !== 'done' ? index : -1).filter(i => i !== -1);

    // Process tests sequentially (BATCH_SIZE = 1) because each test now spawns 4 parallel requests internally.
    const BATCH_SIZE = 1;

    for (let i = 0; i < pendingIndices.length; i += BATCH_SIZE) {
        const batchIndices = pendingIndices.slice(i, i + BATCH_SIZE);

        // 1. Mark this batch as running in UI
        setItems(prev => {
            const next = [...prev];
            batchIndices.forEach(idx => {
                next[idx] = { ...next[idx], status: 'running', errorMessage: undefined };
            });
            return next;
        });

        // 2. Execute requests
        await Promise.all(batchIndices.map(async (index) => {
            const item = items[index];
            const modelOutputs = {
                'Writer (Agent Mode)': item['Writer (Agent Mode)'],
                'Writer (Chat mode)': item['Writer (Chat mode)'],
                'GPT 5.2': item['GPT 5.2'],
                'GS PeM': item['GS PeM'],
                'Gemini': item['Gemini']
            };

            try {
                const analysis = await runVotingSession(item.Prompt, modelOutputs, personas);

                // Update specific item upon completion
                setItems(prev => {
                    const next = [...prev];
                    next[index] = { ...next[index], status: 'done', analysis };
                    return next;
                });
            } catch (error: any) {
                console.error(`Error processing item ${index}`, error);
                // Mark as error so user can see it failed and retry
                setItems(prev => {
                    const next = [...prev];
                    next[index] = { 
                        ...next[index], 
                        status: 'error',
                        errorMessage: error.message || "Unknown error occurred"
                    };
                    return next;
                });
            }
        }));

        // Small delay between items
        if (i + BATCH_SIZE < pendingIndices.length) {
            await new Promise(resolve => setTimeout(resolve, 500));
        }
    }

    setIsProcessing(false);
  };

  const handleExportPDF = async () => {
    // We use the separate hidden PdfReport ref for high quality, detailed exports
    if (!pdfReportRef.current) return;

    try {
        const element = pdfReportRef.current;
        const canvas = await html2canvas(element, { 
            scale: 2, 
            backgroundColor: '#ffffff',
            windowWidth: 800
        });

        const imgData = canvas.toDataURL('image/png');
        const pdf = new jsPDF('p', 'mm', 'a4');
        const pdfWidth = pdf.internal.pageSize.getWidth();
        const pdfHeight = pdf.internal.pageSize.getHeight();
        const imgWidth = canvas.width;
        const imgHeight = canvas.height;
        const ratio = pdfWidth / imgWidth;
        const finalHeight = imgHeight * ratio;

        let heightLeft = finalHeight;
        let position = 0;

        pdf.addImage(imgData, 'PNG', 0, position, pdfWidth, finalHeight);
        heightLeft -= pdfHeight;

        while (heightLeft >= 0) {
          position = heightLeft - finalHeight;
          pdf.addPage();
          pdf.addImage(imgData, 'PNG', 0, position, pdfWidth, finalHeight);
          heightLeft -= pdfHeight;
        }
        pdf.save('CopyCritic_Report.pdf');
    } catch (e) {
        console.error(e);
        alert("Export failed");
    }
  };

  const completedCount = items.filter(i => i.status === 'done').length;

  // Transform ReportItems to ProcessedRows for the PDF component
  const processedRows: ProcessedRow[] = items.map(item => ({
      ...item,
      id: item.id,
      status: item.status === 'done' ? 'completed' : item.status === 'idle' ? 'pending' : 'failed',
      result: item.analysis ? {
          winner: item.analysis.winner,
          counts: item.analysis.counts,
          votes: item.analysis.votes,
          reasoning: item.analysis.summary
      } : undefined
  }));

  return (
    <div className="min-h-screen bg-slate-900 text-slate-100 font-sans pb-20">

      {/* Hidden PDF Render Target */}
      <PdfReport rows={processedRows} reportRef={pdfReportRef} />

      {/* Header */}
      <header className="border-b border-slate-800 bg-slate-900/90 backdrop-blur sticky top-0 z-50">
        <div className="max-w-4xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2 font-bold text-xl">
            <Brain className="text-blue-500" />
            CopyCritic
            <span className="text-[10px] font-normal bg-slate-800 text-slate-400 px-2 py-0.5 rounded-full border border-slate-700">v1.0.0</span>
          </div>
          <div className="text-sm text-slate-500">
             {personas.length > 0 ? `${personas.length} Personas Active` : ''}
          </div>
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-6 py-10">

        {/* STEP 1: UPLOAD */}
        {step === 'upload' && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            <h1 className="text-3xl font-bold text-center mb-4">Upload Validation Data</h1>
            <p className="text-center text-slate-400 mb-10">Upload your Excel sheet containing tests and model outputs.</p>
            <FileUpload onDataLoaded={handleDataLoaded} />
          </div>
        )}

        {/* STEP 2: RECRUIT */}
        {step === 'recruit' && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 text-center py-10">
            <div className="inline-flex p-6 bg-blue-500/10 rounded-full mb-6">
              <Users className="w-12 h-12 text-blue-500" />
            </div>
            <h2 className="text-2xl font-bold mb-4">Recruit Synthetic Panel</h2>
            <p className="text-slate-400 mb-8 max-w-md mx-auto">
              We need to instantiate 100 unique marketing personas (Copywriters, Creative Directors, Growth Hackers) to judge your tests.
            </p>
            <button 
              onClick={handleRecruit}
              disabled={isRecruiting}
              className="bg-blue-600 hover:bg-blue-500 text-white px-8 py-3 rounded-xl font-bold transition-all flex items-center gap-2 mx-auto"
            >
              {isRecruiting ? <Loader2 className="animate-spin" /> : <Users className="w-5 h-5" />}
              Recruit 100 Personas
            </button>
          </div>
        )}

        {/* STEP 3: REPORT VIEW */}
        {step === 'report' && (
          <div className="space-y-8 animate-in fade-in duration-500">

            {/* Persona Panel Summary */}
            <PersonaGrid personas={personas} isGenerating={isRecruiting} />

            {/* Empty State Check */}
            {items.length === 0 ? (
                <div className="bg-slate-800 rounded-xl border border-slate-700 p-12 text-center animate-in fade-in zoom-in-95">
                    <div className="w-16 h-16 bg-slate-700/50 rounded-full flex items-center justify-center mx-auto mb-4">
                        <RefreshCw className="w-8 h-8 text-slate-400" />
                    </div>
                    <h3 className="text-xl font-bold text-white mb-2">No Test Cases Loaded</h3>
                    <p className="text-slate-400 mb-8 max-w-md mx-auto">
                        It looks like the uploaded file didn't contain any valid test rows. Please ensure your Excel headers match the requirements.
                    </p>
                    <button 
                        onClick={() => setStep('upload')}
                        className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2.5 rounded-lg font-bold transition-colors"
                    >
                        Upload Different File
                    </button>
                </div>
            ) : (
                <>
                    {/* Control Bar */}
                    <div className="bg-slate-800 p-4 rounded-xl border border-slate-700 flex items-center justify-between sticky top-20 z-40 shadow-xl">
                      <div className="flex items-center gap-4">
                        <div className="text-sm text-slate-400">
                          <span className="text-white font-bold">{completedCount}</span> / {items.length} Evaluated
                        </div>
                        {isProcessing && (
                            <div className="text-xs text-blue-400 animate-pulse flex items-center gap-1">
                                <Zap className="w-3 h-3" />
                                Processing...
                            </div>
                        )}
                      </div>

                      <div className="flex gap-3">
                         {completedCount > 0 && (
                             <button onClick={handleExportPDF} className="p-2 hover:bg-slate-700 rounded-lg text-slate-400 hover:text-white" title="Export PDF">
                                 <Download className="w-5 h-5" />
                             </button>
                         )}
                         {completedCount < items.length && (
                            <button 
                                onClick={handleRunAll}
                                disabled={isProcessing}
                                className="bg-green-600 hover:bg-green-500 text-white px-6 py-2 rounded-lg font-bold text-sm flex items-center gap-2 transition-all"
                            >
                                {isProcessing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Play className="w-4 h-4 fill-current" />}
                                {items.some(i => i.status !== 'done') && completedCount > 0 ? "Resume Tests" : "Run All Tests"}
                            </button>
                         )}
                      </div>
                    </div>

                    {/* Report Cards List */}
                    <div className="space-y-8" ref={reportContainerRef}>
                      {items.map((item) => (
                        <div key={item.id}>
                            {item.status === 'idle' ? (
                                 <div className="bg-slate-800/30 border border-slate-800 p-6 rounded-xl flex items-center justify-between opacity-50">
                                     <div>
                                         <div className="text-xs font-bold text-slate-600 uppercase">Pending Test</div>
                                         <div className="text-slate-400">{item.Test}</div>
                                     </div>
                                     <div className="h-2 w-2 bg-slate-700 rounded-full"></div>
                                 </div>
                            ) : item.status === 'running' ? (
                                <div className="bg-slate-800 border border-blue-500/30 p-8 rounded-xl flex flex-col items-center justify-center text-center animate-pulse">
                                    <Loader2 className="w-8 h-8 text-blue-500 animate-spin mb-4" />
                                    <h3 className="text-lg font-bold text-white mb-1">Panel is Voting...</h3>
                                    <p className="text-slate-400 text-sm">100 personas reading prompt "{item.Prompt.substring(0, 30)}..."</p>
                                </div>
                            ) : item.status === 'error' ? (
                                <div className="bg-red-900/10 border border-red-500/30 p-6 rounded-xl flex flex-col items-center justify-center text-center">
                                    <AlertTriangle className="w-8 h-8 text-red-500 mb-2" />
                                    <h3 className="text-lg font-bold text-red-400 mb-1">Analysis Failed</h3>
                                    <p className="text-red-200/60 text-sm mb-4 max-w-lg">{item.errorMessage}</p>
                                    <div className="text-xs text-slate-500">
                                        Click "Resume Tests" above to retry this item.
                                    </div>
                                </div>
                            ) : (
                                <TestReportCard item={item} />
                            )}
                        </div>
                      ))}
                    </div>
                </>
            )}

          </div>
        )}

      </main>
    </div>
  );
}

import { GoogleGenAI, Type, Schema, HarmCategory, HarmBlockThreshold } from "@google/genai";
import { Persona, AnalysisResult, ModelKey, MODELS, Vote } from '../types';
