// 2. RUN VOTING SESSION
export const runVotingSession = async (
  promptText: string,
  candidates: Record<ModelKey, string>,
  personas: Persona[]
): Promise<AnalysisResult> => {
  const ai = getAiClient();

  // Map models to simple IDs
  const ID_MAP: Record<string, ModelKey> = {
    'A': 'Writer (Agent Mode)',
    'B': 'Writer (Chat mode)',
    'C': 'GPT 5.2',
    'D': 'GS PeM',
    'E': 'Gemini'
  };

  const REVERSE_MAP: Record<ModelKey, string> = {
    'Writer (Agent Mode)': 'A',
    'Writer (Chat mode)': 'B',
    'GPT 5.2': 'C',
    'GS PeM': 'D',
    'Gemini': 'E'
  };

  let candidateText = "";
  for (const [key, val] of Object.entries(candidates)) {
    // Handle undefined/null values gracefully
    const safeVal = val || "[No content generated]";
    candidateText += `MODEL ${REVERSE_MAP[key as ModelKey]}:\n${safeVal}\n\n`;
  }

  // --- BATCHING STRATEGY ---
  // Reduced to 20 to ensure speed. 100 personas / 20 = 5 parallel requests.
  const BATCH_SIZE = 20;
  const personaBatches = [];
  for (let i = 0; i < personas.length; i += BATCH_SIZE) {
    personaBatches.push(personas.slice(i, i + BATCH_SIZE));
  }

  try {
    const batchPromises = personaBatches.map(async (batchPersonas, batchIndex) => {
        const globalStartIndex = batchIndex * BATCH_SIZE;

        // Re-index locally for the model (0...N) to avoid confusion in the prompt
        const personaList = batchPersonas.map((p, i) => 
            `#${i} ${p.name} (${p.role}): ${p.bias}`
        ).join('\n');

        const systemInstruction = `
            You are simulating a voting panel of specific marketing personas.
            Task: Read the User Prompt and the 5 Model Outputs (A, B, C, D, E).

            1. Analyze the texts based on the personas' biases.
            2. For EACH persona in the provided list, decide which model wrote the best copy.
            3. Provide a brief 'summary' of the consensus.

            IMPORTANT OPTIMIZATIONS: 
            - Use keys 'i' (index), 'c' (choice), 'r' (reason) to save tokens.
            - Keep 'r' extremely brief (max 8 words).
            - Return strictly a JSON object.
        `;

        const userPrompt = `
            ORIGINAL USER PROMPT: "${promptText}"

            --- CANDIDATE TEXTS ---
            ${candidateText}

            --- THE JURY (Subset ${batchIndex + 1}) ---
            ${personaList}

            INSTRUCTIONS:
            Return a JSON object with keys: "summary" (string) and "votes" (array).
            "votes" must be an array of objects: 
            { 
              "i": number (persona index from 0 to ${batchPersonas.length - 1}), 
              "c": "A" | "B" | "C" | "D" | "E", 
              "r": "Short comment" 
            }
        `;

        // Wrap the API call in retry logic and timeout
        return fetchWithRetry(async () => {
            const response: any = await Promise.race([
                ai.models.generateContent({
                  model: 'gemini-3-flash-preview',
                  config: {
                    systemInstruction: systemInstruction,
                    safetySettings: [
                      { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH },
                      { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH },
                      { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH },
                      { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH },
                    ],
                    responseMimeType: 'application/json',
                    responseSchema: {
                      type: Type.OBJECT,
                      properties: {
                        summary: { type: Type.STRING },
                        votes: {
                          type: Type.ARRAY,
                          items: {
                            type: Type.OBJECT,
                            properties: {
                              i: { type: Type.INTEGER, description: "Index" },
                              c: { type: Type.STRING, description: "Choice" },
                              r: { type: Type.STRING, description: "Reason" }
                            }
                          }
                        }
                      }
                    }
                  },
                  contents: userPrompt
                }),
                timeoutPromise(100000) // 100 seconds timeout (increased)
            ]);

            if (!response.text) throw new Error("Empty response");

            const json = JSON.parse(cleanJson(response.text));

            // Map short keys (i, c, r) back to full objects
            const mappedVotes = (json.votes || []).map((v: any) => ({
                personaIndex: (v.i !== undefined ? v.i : -1) + globalStartIndex,
                choice: v.c || 'E',
                reason: v.r || 'No reason provided'
            }));

            return {
                votes: mappedVotes,
                summary: json.summary || ""
            };
        }, 1); // 1 retry allowed
    });

    // Run all batches in parallel
    const results = await Promise.all(batchPromises);

    // --- AGGREGATION ---
    const allVotes: any[] = results.flatMap(r => r.votes);

    const summary = results[0]?.summary || "Analysis completed successfully.";

    const counts: Record<ModelKey, number> = {
      'Writer (Agent Mode)': 0,
      'Writer (Chat mode)': 0,
      'GPT 5.2': 0,
      'GS PeM': 0,
      'Gemini': 0
    };

    const finalVotes: Vote[] = [];

    allVotes.forEach((v: any) => {
      // Robust Parsing
      let choiceChar = v.choice?.toString().toUpperCase().trim().charAt(0) || '';
      const choiceStr = v.choice?.toString().toUpperCase() || '';

      const match = choiceStr.match(/\b([ABCDE])\b/);
      if (match) choiceChar = match[1];

      const modelKey = ID_MAP[choiceChar];

      // Ensure the persona exists (bounds check)
      if (modelKey && personas[v.personaIndex]) {
        counts[modelKey]++;
        finalVotes.push({
          personaName: personas[v.personaIndex].name,
          personaRole: personas[v.personaIndex].role,
          votedFor: modelKey,
          reason: v.reason
        });
      }
    });

    let winner: ModelKey = 'Gemini';
    let max = -1;
    for (const m of MODELS) {
      if (counts[m] > max) {
        max = counts[m];
        winner = m;
      }
    }

    return { winner, counts, votes: finalVotes, summary };

  } catch (e: any) {
    console.error("Evaluation failed", e);
    throw new Error(e.message || "Error during voting session");
  }
};

import { GoogleGenAI, Type, HarmCategory, HarmBlockThreshold } from "@google/genai";
import { Persona, AnalysisResult, ModelKey, MODELS, Vote } from '../types';
