// 2. RUN VOTING SESSION
export const runVotingSession = async (
  promptText: string,
  candidates: Record<string, string>,
  personas: Persona[]
): Promise<AnalysisResult> => {
  const ai = getAiClient();
  const modelNames = Object.keys(candidates);
  const LETTERS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";

  // Dynamic Mapping
  const ID_MAP: Record<string, string> = {};
  const REVERSE_MAP: Record<string, string> = {};

  modelNames.forEach((name, index) => {
    const letter = LETTERS[index] || `M${index}`;
    ID_MAP[letter] = name;
    REVERSE_MAP[name] = letter;
  });

  let candidateText = "";
  for (const [key, val] of Object.entries(candidates)) {
    const safeVal = val || "[No content generated]";
    candidateText += `MODEL ${REVERSE_MAP[key]}: \n${safeVal}\n\n`;
  }

  // --- BATCHING STRATEGY ---
  const BATCH_SIZE = 10;
  const personaBatches = [];
  for (let i = 0; i < personas.length; i += BATCH_SIZE) {
    personaBatches.push(personas.slice(i, i + BATCH_SIZE));
  }

  try {
    const results = await pMap(personaBatches, async (batchPersonas, batchIndex) => {
        const globalStartIndex = batchIndex * BATCH_SIZE;

        const personaList = batchPersonas.map((p, i) => 
            `#${i} ${p.name} (${p.role}): ${p.bias}`
        ).join('\n');

        const availableOptions = modelNames.map(m => REVERSE_MAP[m]).join('|');

        const systemInstruction = `
            You are simulating a voting panel of marketing personas.
            Task: Read the User Prompt and the Model Outputs (${availableOptions}).

            1. Analyze texts based on persona bias.
            2. Decide which model wrote the best copy for EACH persona (#0 to #${batchPersonas.length - 1}).
            3. Provide specific rationales.

            OUTPUT FORMAT:
            Return ONLY a JSON object.
            keys: "summary" (string), "votes" (array).
            votes item: { 
                "i": number (0-${batchPersonas.length - 1}), 
                "c": "${availableOptions}", 
                "choice_reason": "Crisp, specific reason why this model won (max 15 words).",
                "rejection_reason": "Crisp reason why the others were not chosen (max 15 words)."
            }
        `;

        const userPrompt = `
            PROMPT: "${promptText}"

            --- CANDIDATES ---
            ${candidateText}

            --- JURY (Batch ${batchIndex + 1}) ---
            ${personaList}
        `;

        return fetchWithRetry(async () => {
            const response: any = await Promise.race([
                ai.models.generateContent({
                  model: 'gemini-3-pro-preview',
                  config: {
                    systemInstruction: systemInstruction,
                    safetySettings: [
                      { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_NONE },
                      { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_NONE },
                      { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_NONE },
                      { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_NONE },
                    ],
                    responseMimeType: 'application/json',
                    responseSchema: {
                      type: Type.OBJECT,
                      properties: {
                        summary: { type: Type.STRING },
                        votes: {
                          type: Type.ARRAY,
                          items: {
                            type: Type.OBJECT,
                            properties: {
                              i: { type: Type.INTEGER },
                              c: { type: Type.STRING },
                              choice_reason: { type: Type.STRING },
                              rejection_reason: { type: Type.STRING }
                            },
                            required: ["i", "c", "choice_reason", "rejection_reason"]
                          }
                        }
                      }
                    }
                  },
                  contents: userPrompt
                }),
                timeoutPromise(60000) 
            ]);

            if (!response.text) {
                if (response.promptFeedback?.blockReason) {
                    throw new Error(`Blocked: ${response.promptFeedback.blockReason}`);
                }
                throw new Error("Empty response from AI model");
            }

            let json;
            try {
                json = JSON.parse(cleanJson(response.text));
            } catch (e) {
                console.error("JSON Parse Error", response.text);
                throw new Error("Invalid JSON response");
            }

            // Map votes back using the dynamic ID_MAP
            const mappedVotes = (json.votes || []).map((v: any) => ({
                personaIndex: (v.i !== undefined ? v.i : -1) + globalStartIndex,
                choice: v.c || REVERSE_MAP[modelNames[0]], 
                choiceRationale: v.choice_reason || "Good fit",
                rejectionRationale: v.rejection_reason || "Others were worse"
            }));

            return {
                votes: mappedVotes,
                summary: json.summary || ""
            };
        }, 2, 2000); 
    }, 3); 

    // --- AGGREGATION ---
    const allVotes: any[] = results.flatMap(r => r.votes);
    const summary = results[0]?.summary || "Analysis completed.";

    const counts: Record<string, number> = {};
    modelNames.forEach(m => counts[m] = 0);

    const finalVotes: Vote[] = [];

    allVotes.forEach((v: any) => {
      let choiceChar = v.choice?.toString().toUpperCase().trim() || '';
      // Extract just the letter if model hallucinates extra text
      const match = choiceChar.match(/^[A-Z]/); 
      if (match) choiceChar = match[0];

      const modelKey = ID_MAP[choiceChar];

      if (modelKey && personas[v.personaIndex]) {
        counts[modelKey] = (counts[modelKey] || 0) + 1;
        finalVotes.push({
          personaName: personas[v.personaIndex].name,
          personaRole: personas[v.personaIndex].role,
          votedFor: modelKey,
          choiceRationale: v.choiceRationale,
          rejectionRationale: v.rejectionRationale
        });
      }
    });

    let winner: string = modelNames[0];
    let max = -1;
    for (const m of modelNames) {
      if (counts[m] > max) {
        max = counts[m];
        winner = m;
      }
    }

    return { winner, counts, votes: finalVotes, summary };

  } catch (e: any) {
    console.error("Evaluation failed", e);
    throw new Error(e.message || "Error during voting session");
  }
};

// 3. META ANALYSIS (From Session Data)
export const analyzeSessionResults = async (items: ReportItem[]): Promise<MetaAnalysisResult> => {
    const ai = getAiClient();
    const completedItems = items.filter(i => i.status === 'done' && i.analysis);

    if (completedItems.length === 0) throw new Error("No completed tests to analyze");

    // Simplify data to reduce token count but include rationales
    // We sample a few rationales to give the meta-analyst flavor without overloading context window
    const summaryData = completedItems.map((item, idx) => {
        // Get top 3 choice rationales for the winner
        const winner = item.analysis?.winner;
        const topRationales = item.analysis?.votes
            .filter(v => v.votedFor === winner)
            .slice(0, 5)
            .map(v => v.choiceRationale);

        return {
            id: idx,
            test: item.Test,
            prompt: item.Prompt.substring(0, 100),
            winner: item.analysis?.winner,
            voteDistribution: item.analysis?.counts,
            keyRationales: topRationales
        };
    });

    const systemInstruction = `
        You are a Senior Marketing Analyst. 
        Your job is to review a series of A/B tests between different AI models and provide high-level strategic insights.

        Analyze the provided JSON data of test results.
        Pay close attention to the "keyRationales" provided by the personas to understand WHY models are winning.

        Identify:
        1. The Overall Champion (highest win rate).
        2. Specific "Awards" (e.g. Best for Humor, Best for Professionalism, Safest Choice) based on the test topics/summaries.
        3. A deep dive into each model involved (strengths, weaknesses, best use cases).
    `;

    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview', // Using Pro for complex reasoning over dataset
        config: {
            systemInstruction,
            responseMimeType: 'application/json',
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    overallChampion: { type: Type.STRING },
                    executiveSummary: { type: Type.STRING },
                    scenarios: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                title: { type: Type.STRING },
                                winner: { type: Type.STRING },
                                description: { type: Type.STRING },
                                icon: { type: Type.STRING, enum: ['zap', 'shield', 'smile', 'briefcase', 'pen'] }
                            }
                        }
                    },
                    modelInsights: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                modelName: { type: Type.STRING },
                                strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
                                weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
                                bestUseCases: { type: Type.ARRAY, items: { type: Type.STRING } },
                                winRate: { type: Type.NUMBER, description: "Percentage 0-100" }
                            }
                        }
                    }
                }
            }
        },
        contents: JSON.stringify(summaryData)
    });

    if (!response.text) throw new Error("No analysis generated");
    return JSON.parse(cleanJson(response.text));
};

// 4. META ANALYSIS (From PDF)
export const analyzePdfReport = async (base64Pdf: string): Promise<MetaAnalysisResult> => {
    const ai = getAiClient();

    // The PDF is generated via html2canvas, so it consists of screenshots/images of tables and charts.
    // The model needs to visually parse these images.
    const systemInstruction = `
        You are a Senior Marketing Analyst. 
        Read the provided PDF report. 

        IMPORTANT: This PDF contains SCREENSHOTS of data tables, bar charts, and text summaries from a validation tool.
        You must visually analyze the images in the PDF to extract the data.

        Extract and Analyze:
        1. The Overall Champion (which model won the most tests?).
        2. Specific "Awards" (Best for Humor, Professionalism, etc) based on the test prompts/results you see.
        3. Model Deep Dives (Strengths/Weaknesses).

        Return ONLY valid JSON with the following structure:
        {
          "overallChampion": "string",
          "executiveSummary": "string",
          "scenarios": [{ "title": "string", "winner": "string", "description": "string", "icon": "zap" | "shield" | "smile" | "briefcase" | "pen" }],
          "modelInsights": [{ "modelName": "string", "strengths": ["string"], "weaknesses": ["string"], "bestUseCases": ["string"], "winRate": number }]
        }
    `;

    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        config: {
            systemInstruction,
            responseMimeType: 'application/json',
            // NOTE: We do NOT use responseSchema here intentionally. 
            // When dealing with complex visual parsing from PDFs in the Preview model, 
            // strict schema validation can sometimes cause the model to fail or reject valid visual interpretations.
            // We rely on the system instruction and JSON mode to get the correct structure.
        },
        contents: {
            parts: [
                { inlineData: { mimeType: 'application/pdf', data: base64Pdf } },
                { text: "Analyze this visual report and provide the structured JSON insights." }
            ]
        }
    });

    if (!response.text) throw new Error("No analysis generated");

    try {
        return JSON.parse(cleanJson(response.text));
    } catch (e) {
        console.error("Failed to parse PDF analysis JSON", response.text);
        throw new Error("The AI analyzed the PDF but returned invalid JSON.");
    }
};

import React, { useState, useRef, useEffect } from 'react';
import { FileUpload } from './components/FileUpload';
import { TestReportCard } from './components/TestReportCard';
import { PersonaGrid } from './components/PersonaGrid';
import { PdfReport } from './components/PdfReport';
import { InsightsDashboard } from './components/InsightsDashboard';
import { generatePersonas, runVotingSession } from './services/geminiService';
import { ExcelRow, Persona, ReportItem, ProcessedRow, COLOR_PALETTE, Job } from './types';
import { Brain, Users, Play, Loader2, Download, Zap, RefreshCw, AlertTriangle, Tag, PieChart, Save, Database } from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

export default function App() {
  const [step, setStep] = useState<'upload' | 'recruit' | 'report' | 'insights'>('upload');
  const [previousStep, setPreviousStep] = useState<'upload' | 'recruit' | 'report'>('upload');
  const [items, setItems] = useState<ReportItem[]>([]);
  const [personas, setPersonas] = useState<Persona[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isRecruiting, setIsRecruiting] = useState(false);

  // Job History State
  const [savedJobs, setSavedJobs] = useState<Job[]>([]);

  // Dynamic Columns & Colors
  const [modelColumns, setModelColumns] = useState<string[]>([]);
  const [colorMap, setColorMap] = useState<Record<string, string>>({});

  const pdfReportRef = useRef<HTMLDivElement>(null);
  const reportContainerRef = useRef<HTMLDivElement>(null);

  // Load jobs from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem('copyCritic_jobs');
    if (saved) {
        try {
            setSavedJobs(JSON.parse(saved));
        } catch (e) {
            console.error("Failed to load saved jobs", e);
        }
    }
  }, []);

  // 1. Upload Handler
  const handleDataLoaded = (data: ExcelRow[]) => {
    if (data.length > 0) {
      // Dynamically detect model columns (exclude Test, Prompt, and any system keys)
      const firstRow = data[0];
      const cols = Object.keys(firstRow).filter(k => 
        k !== 'Test' && 
        k !== 'Prompt' && 
        k !== '__rowNum__' && 
        k !== 'id'
      );

      setModelColumns(cols);

      // Assign colors round-robin
      const newColors: Record<string, string> = {};
      cols.forEach((col, i) => {
        newColors[col] = COLOR_PALETTE[i % COLOR_PALETTE.length];
      });
      setColorMap(newColors);
    }

    const reportItems: ReportItem[] = data.map((row, i) => ({
      ...row,
      id: `test-${i}`,
      status: 'idle'
    }));
    setItems(reportItems);
    setStep('recruit');
  };

  // 2. Recruit Handler
  const handleRecruit = async () => {
    setIsRecruiting(true);
    await new Promise(r => setTimeout(r, 800));
    const p = await generatePersonas(false);
    setPersonas(p);
    setIsRecruiting(false);
    setStep('report');
  };

  // 3. Run All Handler
  const handleRunAll = async () => {
    setIsProcessing(true);

    const pendingIndices = items.map((item, index) => item.status !== 'done' ? index : -1).filter(i => i !== -1);
    const BATCH_SIZE = 1;

    for (let i = 0; i < pendingIndices.length; i += BATCH_SIZE) {
        const batchIndices = pendingIndices.slice(i, i + BATCH_SIZE);

        setItems(prev => {
            const next = [...prev];
            batchIndices.forEach(idx => {
                next[idx] = { ...next[idx], status: 'running', errorMessage: undefined };
            });
            return next;
        });

        await Promise.all(batchIndices.map(async (index) => {
            const item = items[index];

            // Construct dynamic candidates object
            const candidates: Record<string, string> = {};
            modelColumns.forEach(col => {
                candidates[col] = item[col] || "";
            });

            try {
                const analysis = await runVotingSession(item.Prompt, candidates, personas);

                setItems(prev => {
                    const next = [...prev];
                    next[index] = { ...next[index], status: 'done', analysis };
                    return next;
                });
            } catch (error: any) {
                console.error(`Error processing item ${index}`, error);
                setItems(prev => {
                    const next = [...prev];
                    next[index] = { 
                        ...next[index], 
                        status: 'error',
                        errorMessage: error.message || "Unknown error occurred"
                    };
                    return next;
                });
            }
        }));

        if (i + BATCH_SIZE < pendingIndices.length) {
            await new Promise(resolve => setTimeout(resolve, 500));
        }
    }

    setIsProcessing(false);
  };

  const handleSaveJob = () => {
    const jobName = prompt("Enter a name for this job run:", `Run ${new Date().toLocaleTimeString()}`);
    if (!jobName) return;

    const newJob: Job = {
        id: crypto.randomUUID(),
        timestamp: Date.now(),
        name: jobName,
        items,
        personas
    };

    const updatedJobs = [newJob, ...savedJobs];
    setSavedJobs(updatedJobs);
    localStorage.setItem('copyCritic_jobs', JSON.stringify(updatedJobs));
    alert("Job saved successfully!");
  };

  const handleExportPDF = async () => {
    if (!pdfReportRef.current) return;
    try {
        const element = pdfReportRef.current;
        const canvas = await html2canvas(element, { 
            scale: 2, 
            backgroundColor: '#ffffff',
            windowWidth: 800
        });

        const imgData = canvas.toDataURL('image/png');
        const pdf = new jsPDF('p', 'mm', 'a4');
        const pdfWidth = pdf.internal.pageSize.getWidth();
        const pdfHeight = pdf.internal.pageSize.getHeight();
        const imgWidth = canvas.width;
        const imgHeight = canvas.height;
        const ratio = pdfWidth / imgWidth;
        const finalHeight = imgHeight * ratio;

        let heightLeft = finalHeight;
        let position = 0;

        pdf.addImage(imgData, 'PNG', 0, position, pdfWidth, finalHeight);
        heightLeft -= pdfHeight;

        while (heightLeft >= 0) {
          position = heightLeft - finalHeight;
          pdf.addPage();
          pdf.addImage(imgData, 'PNG', 0, position, pdfWidth, finalHeight);
          heightLeft -= pdfHeight;
        }
        pdf.save('CopyCritic_Report.pdf');
    } catch (e) {
        console.error(e);
        alert("Export failed");
    }
  };

  const completedCount = items.filter(i => i.status === 'done').length;

  const processedRows: ProcessedRow[] = items.map(item => ({
      ...item,
      id: item.id,
      status: item.status === 'done' ? 'completed' : item.status === 'idle' ? 'pending' : 'failed',
      result: item.analysis ? {
          winner: item.analysis.winner,
          counts: item.analysis.counts,
          votes: item.analysis.votes,
          reasoning: item.analysis.summary
      } : undefined
  }));

  const goToInsights = () => {
    if (step !== 'insights') {
        setPreviousStep(step);
        setStep('insights');
    }
  };

  const backFromInsights = () => {
    setStep(previousStep);
  };

  return (
    <div className="min-h-screen bg-slate-900 text-slate-100 font-sans pb-20">

      {/* Hidden PDF Render Target */}
      <PdfReport 
        rows={processedRows} 
        reportRef={pdfReportRef} 
        modelColumns={modelColumns}
        colorMap={colorMap}
      />

      {/* Header */}
      <header className="border-b border-slate-800 bg-slate-900/90 backdrop-blur sticky top-0 z-50">
        <div className="max-w-4xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2 font-bold text-xl cursor-pointer" onClick={() => step === 'insights' ? backFromInsights() : null}>
            <Brain className="text-blue-500" />
            CopyCritic
            <span className="text-[10px] font-medium bg-green-500/10 text-green-400 px-2 py-0.5 rounded-full border border-green-500/20 flex items-center gap-1">
              <Tag className="w-3 h-3" />
              v1.5.0
            </span>
          </div>
          <div className="flex items-center gap-4">
            <div className="text-sm text-slate-500">
               {personas.length > 0 ? `${personas.length} Personas Active` : ''}
            </div>
            {step !== 'insights' && (
