  colorMap: Record<string, string>;
}

export const PdfReport: React.FC<PdfReportProps> = ({ rows, reportRef, modelColumns, colorMap }) => {
  const completedRows = rows.filter(r => r.status === 'completed' && r.result);

  return (
    <div className="fixed left-[-9999px] top-0">
      <div 
        ref={reportRef} 
        className="w-[800px] min-h-screen bg-white text-slate-900 p-12 font-sans"
        style={{ colorScheme: 'light' }}
      >
        {/* Title Page */}
        <div className="mb-12 border-b-2 border-slate-900 pb-6">
          <div className="flex items-center gap-3 mb-2">
            <div className="bg-blue-600 p-2 rounded-lg">
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2">
                   <path d="M12 2a10 10 0 1 0 10 10 4 4 0 0 1-5-5 4 4 0 0 1-5-5" />
                </svg>
            </div>
            <h1 className="text-3xl font-bold text-slate-900">Copy Critic Validation Report</h1>
          </div>
          <p className="text-slate-500 text-lg">Synthetic Persona Panel Analysis</p>
          <div className="mt-4 text-sm text-slate-400">
            Generated on {new Date().toLocaleDateString()}
          </div>
        </div>

        {/* Executive Summary */}
        <div className="mb-12">
            <h2 className="text-xl font-bold mb-4 uppercase tracking-wider text-slate-700">Executive Summary</h2>
            <div className="bg-slate-50 border border-slate-200 rounded-lg overflow-hidden">
                <table className="w-full text-sm">
                    <thead className="bg-slate-100 border-b border-slate-200">
                        <tr>
                            <th className="p-3 text-left font-semibold text-slate-600">Test / Variation</th>
                            <th className="p-3 text-left font-semibold text-slate-600">Winning Model</th>
                            <th className="p-3 text-right font-semibold text-slate-600">Vote %</th>
                        </tr>
                    </thead>
                    <tbody>
                        {completedRows.map(row => {
                            const winner = row.result!.winner;
                            const voteCount = row.result?.counts?.[winner] ?? 0;
                            return (
                                <tr key={row.id} className="border-b border-slate-100">
                                    <td className="p-3 font-medium text-slate-800">{row.Test}</td>
                                    <td className="p-3">
                                        <span className="px-2 py-1 rounded text-xs font-bold text-white" style={{ backgroundColor: colorMap[winner] || '#94a3b8' }}>
                                            {winner}
                                        </span>
                                    </td>
                                    <td className="p-3 text-right text-slate-600">{voteCount}%</td>
                                </tr>
                            );
                        })}
                    </tbody>
                </table>
            </div>
        </div>

        {/* Detailed Results */}
        <div className="space-y-12">
            {completedRows.map((row, idx) => {
                const winner = row.result?.winner || "";
                const losers = modelColumns.filter(m => m !== winner);
                const votes = row.result?.votes || [];
                const allRejections = votes.map(v => v.rejectionRationale).filter(Boolean);

                // Logic to prioritize critiques that mention loser names
                const specificRejections = allRejections.filter(r => 
                    losers.some(l => r.toLowerCase().includes(l.toLowerCase()))
                );
                const genericRejections = allRejections.filter(r => 
                    !losers.some(l => r.toLowerCase().includes(l.toLowerCase()))
                );

                const topRejections = [...new Set([...specificRejections, ...genericRejections])].slice(0, 3);

                return (
                    <div key={row.id} className="break-inside-avoid page-break-auto">
                        <div className="flex items-center gap-3 mb-4 pb-2 border-b border-slate-200">
                            <span className="text-2xl font-bold text-slate-300">#{idx + 1}</span>
                            <div>
                                <h3 className="text-xl font-bold text-slate-900">{row.Test}</h3>
                                <div className="text-xs text-slate-500 line-clamp-1">{row.Prompt.substring(0, 100)}...</div>
                            </div>
                        </div>

                        <div className="grid grid-cols-12 gap-6 mb-6">
                            <div className="col-span-8">
                                <div className="bg-slate-50 p-4 rounded-lg border border-slate-200 mb-4">
                                    <h4 className="text-xs font-bold uppercase text-slate-500 mb-2">Overall Analysis</h4>
                                    <p className="text-sm text-slate-700 leading-relaxed">{row.result?.reasoning}</p>
                                </div>

                                {/* Static Bar Chart for PDF */}
                                <div className="h-40 w-full mb-4">
                                    <ResponsiveContainer width="100%" height="100%">
                                        <BarChart 
                                            data={modelColumns.map(m => ({ name: m, votes: row.result?.counts?.[m] ?? 0 }))} 
                                            layout="vertical"
                                            margin={{ left: 50, right: 20 }}
                                        >
                                            <XAxis type="number" hide />
                                            <YAxis dataKey="name" type="category" width={100} tick={{fontSize: 10}} />
                                            <Bar dataKey="votes" barSize={20} isAnimationActive={false} minPointSize={2}>
                                                {modelColumns.map((m, i) => (
                                                    <Cell key={i} fill={colorMap[m] || '#94a3b8'} />
                                                ))}
                                                <LabelList dataKey="votes" position="right" fontSize={10} formatter={(v: number) => `${v}%`} />
                                            </Bar>
                                        </BarChart>
                                    </ResponsiveContainer>
                                </div>

                                {/* Rejection Reasons in PDF */}
                                {topRejections.length > 0 && (
                                    <div className="bg-red-50 p-4 rounded-lg border border-red-100">
                                        <h4 className="text-xs font-bold text-red-600 uppercase mb-2 flex items-center gap-1">
                                            <AlertOctagon className="w-3 h-3" /> Rejection Factors
                                        </h4>
                                        <ul className="space-y-1">
                                            {topRejections.map((reason, rIdx) => (
                                                <li key={rIdx} className="text-xs text-slate-600 flex items-start gap-2">
                                                    <span className="text-red-400 font-bold">•</span>
                                                    {reason}
                                                </li>
                                            ))}
                                        </ul>
                                    </div>
                                )}
                            </div>

                            <div className="col-span-4">
                                <div className="flex flex-col gap-2">
                                    <div className="text-xs font-bold uppercase text-slate-500 mb-1">Winning Copy</div>
                                    <div className="p-3 bg-green-50 border border-green-200 rounded-lg text-xs text-slate-700 whitespace-pre-wrap leading-relaxed max-h-64 overflow-hidden relative">
                                        {row[row.result!.winner]}
                                        <div className="absolute top-2 right-2">
                                            <Trophy className="w-4 h-4 text-green-600" />
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Detailed Voting Table */}
                        <div className="mt-8">
                            <h4 className="text-sm font-bold text-slate-800 mb-3 flex items-center gap-2">
                                <User className="w-4 h-4" />
                                Individual Persona Votes (100)
                            </h4>
                            <div className="bg-white border border-slate-200 rounded-lg overflow-hidden">
                                <table className="w-full text-xs">
                                    <thead className="bg-slate-50 border-b border-slate-200">
                                        <tr>
                                            <th className="p-2 text-left font-semibold text-slate-600 w-1/4">Persona</th>
                                            <th className="p-2 text-left font-semibold text-slate-600 w-1/4">Role</th>
                                            <th className="p-2 text-left font-semibold text-slate-600 w-1/6">Vote</th>
                                            <th className="p-2 text-left font-semibold text-slate-600">Rationale</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {row.result?.votes?.map((vote, vIdx) => (
                                            <tr key={vIdx} className="border-b border-slate-100 last:border-0 hover:bg-slate-50/50">
                                                <td className="p-2 font-medium text-slate-800">{vote.personaName}</td>
                                                <td className="p-2 text-slate-500">{vote.personaRole}</td>
                                                <td className="p-2">
                                                    <span 
                                                        className="px-1.5 py-0.5 rounded text-[10px] font-bold text-white whitespace-nowrap"
                                                        style={{ backgroundColor: colorMap[vote.votedFor] || '#94a3b8' }}
                                                    >
                                                        {vote.votedFor}
                                                    </span>
                                                </td>
                                                <td className="p-2 text-slate-600">
                                                    <div className="mb-1"><span className="text-green-600 font-semibold">Yes:</span> {vote.choiceRationale}</div>
                                                    {vote.rejectionRationale && <div><span className="text-red-500 font-semibold">No:</span> {vote.rejectionRationale}</div>}
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                );
            })}
        </div>

        {/* Footer */}
        <div className="mt-12 pt-6 border-t border-slate-200 text-center text-xs text-slate-400">
            Copy Critic Validation System • Powered by Gemini
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { FileUpload } from './components/FileUpload';
import { TestReportCard } from './components/TestReportCard';
import { PersonaGrid } from './components/PersonaGrid';
import { PdfReport } from './components/PdfReport';
import { InsightsDashboard } from './components/InsightsDashboard';
import { generatePersonas, runVotingSession } from './services/geminiService';
import { ExcelRow, Persona, ReportItem, ProcessedRow, COLOR_PALETTE, Job } from './types';
import { Brain, Users, Play, Loader2, Download, Zap, RefreshCw, AlertTriangle, Tag, PieChart, Save, Database } from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

export default function App() {
  const [step, setStep] = useState<'upload' | 'recruit' | 'report' | 'insights'>('upload');
  const [previousStep, setPreviousStep] = useState<'upload' | 'recruit' | 'report'>('upload');
  const [items, setItems] = useState<ReportItem[]>([]);
  const [personas, setPersonas] = useState<Persona[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isRecruiting, setIsRecruiting] = useState(false);

  // Job History State
  const [savedJobs, setSavedJobs] = useState<Job[]>([]);

  // Dynamic Columns & Colors
  const [modelColumns, setModelColumns] = useState<string[]>([]);
  const [colorMap, setColorMap] = useState<Record<string, string>>({});

  const pdfReportRef = useRef<HTMLDivElement>(null);
  const reportContainerRef = useRef<HTMLDivElement>(null);

  // Load jobs from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem('copyCritic_jobs');
    if (saved) {
        try {
            setSavedJobs(JSON.parse(saved));
        } catch (e) {
            console.error("Failed to load saved jobs", e);
        }
    }
  }, []);

  // 1. Upload Handler
  const handleDataLoaded = (data: ExcelRow[]) => {
    if (data.length > 0) {
      // Dynamically detect model columns (exclude Test, Prompt, and any system keys)
      const firstRow = data[0];
      const cols = Object.keys(firstRow).filter(k => 
        k !== 'Test' && 
        k !== 'Prompt' && 
        k !== '__rowNum__' && 
        k !== 'id'
      );

      setModelColumns(cols);

      // Assign colors round-robin
      const newColors: Record<string, string> = {};
      cols.forEach((col, i) => {
        newColors[col] = COLOR_PALETTE[i % COLOR_PALETTE.length];
      });
      setColorMap(newColors);
    }

    const reportItems: ReportItem[] = data.map((row, i) => ({
      ...row,
      id: `test-${i}`,
      status: 'idle'
    }));
    setItems(reportItems);
    setStep('recruit');
  };

  // 2. Recruit Handler
  const handleRecruit = async () => {
    setIsRecruiting(true);
    await new Promise(r => setTimeout(r, 800));
    const p = await generatePersonas(false);
    setPersonas(p);
    setIsRecruiting(false);
    setStep('report');
  };

  // 3. Run All Handler
  const handleRunAll = async () => {
    setIsProcessing(true);

    const pendingIndices = items.map((item, index) => item.status !== 'done' ? index : -1).filter(i => i !== -1);
    const BATCH_SIZE = 1;

    for (let i = 0; i < pendingIndices.length; i += BATCH_SIZE) {
        const batchIndices = pendingIndices.slice(i, i + BATCH_SIZE);

        setItems(prev => {
            const next = [...prev];
            batchIndices.forEach(idx => {
                next[idx] = { ...next[idx], status: 'running', errorMessage: undefined };
            });
            return next;
        });

        await Promise.all(batchIndices.map(async (index) => {
            const item = items[index];

            // Construct dynamic candidates object
            const candidates: Record<string, string> = {};
            modelColumns.forEach(col => {
                candidates[col] = item[col] || "";
            });

            try {
                const analysis = await runVotingSession(item.Prompt, candidates, personas);

                setItems(prev => {
                    const next = [...prev];
                    next[index] = { ...next[index], status: 'done', analysis };
                    return next;
                });
            } catch (error: any) {
                console.error(`Error processing item ${index}`, error);
                setItems(prev => {
                    const next = [...prev];
                    next[index] = { 
                        ...next[index], 
                        status: 'error',
                        errorMessage: error.message || "Unknown error occurred"
                    };
                    return next;
                });
            }
        }));

        if (i + BATCH_SIZE < pendingIndices.length) {
            await new Promise(resolve => setTimeout(resolve, 500));
        }
    }

    setIsProcessing(false);
  };

  const handleSaveJob = () => {
    const jobName = prompt("Enter a name for this job run:", `Run ${new Date().toLocaleTimeString()}`);
    if (!jobName) return;

    const newJob: Job = {
        id: crypto.randomUUID(),
        timestamp: Date.now(),
        name: jobName,
        items,
        personas
    };

    const updatedJobs = [newJob, ...savedJobs];
    setSavedJobs(updatedJobs);
    localStorage.setItem('copyCritic_jobs', JSON.stringify(updatedJobs));
    alert("Job saved successfully!");
  };

  const handleExportPDF = async () => {
    if (!pdfReportRef.current) {
        alert("Report reference not found. Please try again.");
        return;
    }

    // Show a temporary loading state or toast if needed
    const originalTitle = document.title;
    document.title = "Generating PDF...";

    try {
        const element = pdfReportRef.current;

        // Ensure fonts are loaded before capture
        await document.fonts.ready;

        const canvas = await html2canvas(element, { 
            scale: 2, 
            backgroundColor: '#ffffff',
            windowWidth: 800,
            useCORS: true,
            logging: false,
            x: 0,
            y: 0,
            scrollX: 0,
            scrollY: 0
        });

        if (canvas.width === 0 || canvas.height === 0) {
            throw new Error("Canvas generated was empty. Please verify data.");
        }

        const imgData = canvas.toDataURL('image/png');
        const pdf = new jsPDF('p', 'mm', 'a4');
        const pdfWidth = pdf.internal.pageSize.getWidth();
        const pdfHeight = pdf.internal.pageSize.getHeight();
        const imgWidth = canvas.width;
        const imgHeight = canvas.height;
        const ratio = pdfWidth / imgWidth;
        const finalHeight = imgHeight * ratio;

        let heightLeft = finalHeight;
        let position = 0;

        pdf.addImage(imgData, 'PNG', 0, position, pdfWidth, finalHeight);
        heightLeft -= pdfHeight;

        while (heightLeft >= 0) {
          position = heightLeft - finalHeight;
          pdf.addPage();
          pdf.addImage(imgData, 'PNG', 0, position, pdfWidth, finalHeight);
          heightLeft -= pdfHeight;
        }
        pdf.save('CopyCritic_Report.pdf');
    } catch (e: any) {
        console.error(e);
        alert(`Export failed: ${e.message || 'Unknown error'}`);
    } finally {
        document.title = originalTitle;
    }
  };

  const completedCount = items.filter(i => i.status === 'done').length;

  const processedRows: ProcessedRow[] = items.map(item => ({
      ...item,
      id: item.id,
      status: item.status === 'done' ? 'completed' : item.status === 'idle' ? 'pending' : 'failed',
      result: item.analysis ? {
          winner: item.analysis.winner,
          counts: item.analysis.counts,
          votes: item.analysis.votes,
          reasoning: item.analysis.summary
      } : undefined
  }));

  const goToInsights = () => {
    if (step !== 'insights') {
        setPreviousStep(step);
        setStep('insights');
    }
  };

  const backFromInsights = () => {
    setStep(previousStep);
  };

  return (
    <div className="min-h-screen bg-slate-900 text-slate-100 font-sans pb-20">

      {/* Hidden PDF Render Target - Always rendered but hidden via absolute/z-index */}
      <PdfReport 
        rows={processedRows} 
        reportRef={pdfReportRef} 
        modelColumns={modelColumns}
        colorMap={colorMap}
      />

      {/* Header */}
      <header className="border-b border-slate-800 bg-slate-900/90 backdrop-blur sticky top-0 z-50">
        <div className="max-w-4xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2 font-bold text-xl cursor-pointer" onClick={() => step === 'insights' ? backFromInsights() : null}>
            <Brain className="text-blue-500" />
            CopyCritic
            <span className="text-[10px] font-medium bg-green-500/10 text-green-400 px-2 py-0.5 rounded-full border border-green-500/20 flex items-center gap-1">
              <Tag className="w-3 h-3" />
              v1.5.1
            </span>
          </div>
          <div className="flex items-center gap-4">
            <div className="text-sm text-slate-500">
               {personas.length > 0 ? `${personas.length} Personas Active` : ''}
            </div>
            {step !== 'insights' && (
                <button 
                    onClick={goToInsights}
                    className="text-xs bg-slate-800 hover:bg-slate-700 text-blue-400 border border-slate-700 px-3 py-1.5 rounded-lg font-medium transition-colors flex items-center gap-2"
                >
                    <PieChart className="w-3 h-3" />
                    Meta Analysis
                </button>
            )}
          </div>
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-6 py-10">

        {step === 'insights' ? (
            <InsightsDashboard 
                currentItems={items} 
                onBack={backFromInsights}
                colorMap={colorMap}
                savedJobs={savedJobs}
            />
        ) : (
            <>
                {step === 'upload' && (
                  <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                    <h1 className="text-3xl font-bold text-center mb-4">Upload Validation Data</h1>
                    <p className="text-center text-slate-400 mb-10">Upload your Excel sheet containing tests and model outputs.</p>
                    <FileUpload onDataLoaded={handleDataLoaded} />
                  </div>
                )}

                {step === 'recruit' && (
                  <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 text-center py-10">
                    <div className="inline-flex p-6 bg-blue-500/10 rounded-full mb-6">
                      <Users className="w-12 h-12 text-blue-500" />
                    </div>
                    <h2 className="text-2xl font-bold mb-4">Recruit Synthetic Panel</h2>
                    <p className="text-slate-400 mb-8 max-w-md mx-auto">
                      We need to instantiate 100 unique marketing personas to judge your {modelColumns.length} models: <br/>
                      <span className="text-blue-400 font-mono text-xs">{modelColumns.join(', ')}</span>
                    </p>
                    <button 
                      onClick={handleRecruit}
                      disabled={isRecruiting}
                      className="bg-blue-600 hover:bg-blue-500 text-white px-8 py-3 rounded-xl font-bold transition-all flex items-center gap-2 mx-auto"
                    >
                      {isRecruiting ? <Loader2 className="animate-spin" /> : <Users className="w-5 h-5" />}
                      Recruit 100 Personas
                    </button>
                  </div>
                )}

                {step === 'report' && (
                  <div className="space-y-8 animate-in fade-in duration-500">

                    <PersonaGrid personas={personas} isGenerating={isRecruiting} />

                    {items.length === 0 ? (
                        <div className="bg-slate-800 rounded-xl border border-slate-700 p-12 text-center animate-in fade-in zoom-in-95">
                            <div className="w-16 h-16 bg-slate-700/50 rounded-full flex items-center justify-center mx-auto mb-4">
                                <RefreshCw className="w-8 h-8 text-slate-400" />
                            </div>
                            <h3 className="text-xl font-bold text-white mb-2">No Test Cases Loaded</h3>
                            <button onClick={() => setStep('upload')} className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2.5 rounded-lg font-bold transition-colors">
                                Upload Different File
                            </button>
                        </div>
                    ) : (
                        <>
                            <div className="bg-slate-800 p-4 rounded-xl border border-slate-700 flex items-center justify-between sticky top-20 z-40 shadow-xl">
                              <div className="flex items-center gap-4">
                                <div className="text-sm text-slate-400">
                                  <span className="text-white font-bold">{completedCount}</span> / {items.length} Evaluated
                                </div>
                                {isProcessing && (
                                    <div className="text-xs text-blue-400 animate-pulse flex items-center gap-1">
                                        <Zap className="w-3 h-3" />
                                        Processing...
                                    </div>
                                )}
                              </div>

                              <div className="flex gap-3">
                                 {completedCount > 0 && !isProcessing && (
                                     <button 
                                        onClick={handleSaveJob}
                                        className="p-2 hover:bg-slate-700 rounded-lg text-slate-400 hover:text-white" 
                                        title="Save Job to History"
                                    >
                                        <Save className="w-5 h-5" />
                                    </button>
                                 )}
                                 {completedCount > 0 && (
                                     <button onClick={handleExportPDF} className="p-2 hover:bg-slate-700 rounded-lg text-slate-400 hover:text-white" title="Export PDF">
                                         <Download className="w-5 h-5" />
                                     </button>
                                 )}
                                 {completedCount < items.length && (
                                    <button 
                                        onClick={handleRunAll}
                                        disabled={isProcessing}
                                        className="bg-green-600 hover:bg-green-500 text-white px-6 py-2 rounded-lg font-bold text-sm flex items-center gap-2 transition-all"
                                    >
                                        {isProcessing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Play className="w-4 h-4 fill-current" />}
                                        {items.some(i => i.status !== 'done') && completedCount > 0 ? "Resume Tests" : "Run All Tests"}
                                    </button>
                                 )}
                              </div>
                            </div>

                            <div className="space-y-8" ref={reportContainerRef}>
                              {items.map((item) => (
                                <div key={item.id}>
                                    {item.status === 'idle' ? (
                                         <div className="bg-slate-800/30 border border-slate-800 p-6 rounded-xl flex items-center justify-between opacity-50">
                                             <div>
                                                 <div className="text-xs font-bold text-slate-600 uppercase">Pending Test</div>
                                                 <div className="text-slate-400">{item.Test}</div>
                                             </div>
                                             <div className="h-2 w-2 bg-slate-700 rounded-full"></div>
                                         </div>
                                    ) : item.status === 'running' ? (
                                        <div className="bg-slate-800 border border-blue-500/30 p-8 rounded-xl flex flex-col items-center justify-center text-center animate-pulse">
                                            <Loader2 className="w-8 h-8 text-blue-500 animate-spin mb-4" />
                                            <h3 className="text-lg font-bold text-white mb-1">Panel is Voting...</h3>
                                            <p className="text-slate-400 text-sm">100 personas reading prompt "{item.Prompt.substring(0, 30)}..."</p>
                                        </div>
                                    ) : item.status === 'error' ? (
                                        <div className="bg-red-900/10 border border-red-500/30 p-6 rounded-xl flex flex-col items-center justify-center text-center">
                                            <AlertTriangle className="w-8 h-8 text-red-500 mb-2" />
                                            <h3 className="text-lg font-bold text-red-400 mb-1">Analysis Failed</h3>
                                            <p className="text-red-200/60 text-sm mb-4 max-w-lg">{item.errorMessage}</p>
                                        </div>
                                    ) : (
                                        <TestReportCard 
                                            item={item} 
                                            modelColumns={modelColumns} 
                                            colorMap={colorMap} 
                                        />
                                    )}
                                </div>
                              ))}
                            </div>
                        </>
                    )}
                  </div>
                )}
            </>
        )}
      </main>
    </div>
  );
}

import React from 'react';
import { ProcessedRow } from '../types';
import { BarChart, Bar, XAxis, YAxis, Cell, ResponsiveContainer, LabelList } from 'recharts';
import { Trophy, User, AlertOctagon } from 'lucide-react';

interface PdfReportProps {
  rows: ProcessedRow[];
  reportRef: React.RefObject<HTMLDivElement | null>;
  modelColumns: string[];
  colorMap: Record<string, string>;
}

export const PdfReport: React.FC<PdfReportProps> = ({ rows, reportRef, modelColumns, colorMap }) => {
  const completedRows = rows.filter(r => r.status === 'completed' && r.result);

  return (
    <div style={{ position: 'absolute', top: 0, left: '-10000px', width: '800px', zIndex: -50 }}>
      <div 
        ref={reportRef} 
        className="min-h-screen bg-white text-slate-900 p-12 font-sans"
        style={{ width: '800px', colorScheme: 'light' }}
      >
        {/* Title Page */}
        <div className="mb-12 border-b-2 border-slate-900 pb-6">
          <div className="flex items-center gap-3 mb-2">
            <div className="bg-blue-600 p-2 rounded-lg">
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2">
                   <path d="M12 2a10 10 0 1 0 10 10 4 4 0 0 1-5-5 4 4 0 0 1-5-5" />
                </svg>
            </div>
            <h1 className="text-3xl font-bold text-slate-900">Copy Critic Validation Report</h1>
          </div>
          <p className="text-slate-500 text-lg">Synthetic Persona Panel Analysis</p>
          <div className="mt-4 text-sm text-slate-400">
            Generated on {new Date().toLocaleDateString()}
          </div>
        </div>

        {/* Executive Summary */}
        <div className="mb-12">
            <h2 className="text-xl font-bold mb-4 uppercase tracking-wider text-slate-700">Executive Summary</h2>
            <div className="bg-slate-50 border border-slate-200 rounded-lg overflow-hidden">
                <table className="w-full text-sm">
                    <thead className="bg-slate-100 border-b border-slate-200">
                        <tr>
                            <th className="p-3 text-left font-semibold text-slate-600">Test / Variation</th>
                            <th className="p-3 text-left font-semibold text-slate-600">Winning Model</th>
                            <th className="p-3 text-right font-semibold text-slate-600">Vote %</th>
                        </tr>
                    </thead>
                    <tbody>
                        {completedRows.map(row => {
                            const winner = row.result!.winner;
                            const voteCount = row.result?.counts?.[winner] ?? 0;
                            return (
                                <tr key={row.id} className="border-b border-slate-100">
                                    <td className="p-3 font-medium text-slate-800">{row.Test}</td>
                                    <td className="p-3">
                                        <span className="px-2 py-1 rounded text-xs font-bold text-white" style={{ backgroundColor: colorMap[winner] || '#94a3b8' }}>
                                            {winner}
                                        </span>
                                    </td>
                                    <td className="p-3 text-right text-slate-600">{voteCount}%</td>
                                </tr>
                            );
                        })}
                    </tbody>
                </table>
            </div>
        </div>

        {/* Detailed Results */}
        <div className="space-y-12">
            {completedRows.map((row, idx) => {
                const winner = row.result?.winner || "";
                const losers = modelColumns.filter(m => m !== winner);
                const votes = row.result?.votes || [];
                const allRejections = votes.map(v => v.rejectionRationale).filter(Boolean);

                // Logic to prioritize critiques that mention loser names
                const specificRejections = allRejections.filter(r => 
                    losers.some(l => r.toLowerCase().includes(l.toLowerCase()))
                );
                const genericRejections = allRejections.filter(r => 
                    !losers.some(l => r.toLowerCase().includes(l.toLowerCase()))
                );

                const topRejections = [...new Set([...specificRejections, ...genericRejections])].slice(0, 3);

                return (
                    <div key={row.id} className="break-inside-avoid page-break-auto">
                        <div className="flex items-center gap-3 mb-4 pb-2 border-b border-slate-200">
                            <span className="text-2xl font-bold text-slate-300">#{idx + 1}</span>
                            <div>
                                <h3 className="text-xl font-bold text-slate-900">{row.Test}</h3>
                                <div className="text-xs text-slate-500 line-clamp-1">{row.Prompt.substring(0, 100)}...</div>
                            </div>
                        </div>

                        <div className="grid grid-cols-12 gap-6 mb-6">
                            <div className="col-span-8">
                                <div className="bg-slate-50 p-4 rounded-lg border border-slate-200 mb-4">
                                    <h4 className="text-xs font-bold uppercase text-slate-500 mb-2">Overall Analysis</h4>
                                    <p className="text-sm text-slate-700 leading-relaxed">{row.result?.reasoning}</p>
                                </div>

                                {/* Static Bar Chart for PDF */}
                                <div className="h-40 w-full mb-4">
                                    <ResponsiveContainer width="100%" height="100%">
                                        <BarChart 
                                            data={modelColumns.map(m => ({ name: m, votes: row.result?.counts?.[m] ?? 0 }))} 
                                            layout="vertical"
                                            margin={{ left: 50, right: 20 }}
                                        >
                                            <XAxis type="number" hide />
                                            <YAxis dataKey="name" type="category" width={100} tick={{fontSize: 10}} />
                                            <Bar dataKey="votes" barSize={20} isAnimationActive={false} minPointSize={2}>
                                                {modelColumns.map((m, i) => (
                                                    <Cell key={i} fill={colorMap[m] || '#94a3b8'} />
                                                ))}
                                                <LabelList dataKey="votes" position="right" fontSize={10} formatter={(v: number) => `${v}%`} />
                                            </Bar>
                                        </BarChart>
                                    </ResponsiveContainer>
                                </div>

                                {/* Rejection Reasons in PDF */}
                                {topRejections.length > 0 && (
                                    <div className="bg-red-50 p-4 rounded-lg border border-red-100">
                                        <h4 className="text-xs font-bold text-red-600 uppercase mb-2 flex items-center gap-1">
                                            <AlertOctagon className="w-3 h-3" /> Rejection Factors
                                        </h4>
                                        <ul className="space-y-1">
                                            {topRejections.map((reason, rIdx) => (
                                                <li key={rIdx} className="text-xs text-slate-600 flex items-start gap-2">
                                                    <span className="text-red-400 font-bold">•</span>
                                                    {reason}
                                                </li>
                                            ))}
                                        </ul>
                                    </div>
                                )}
                            </div>

                            <div className="col-span-4">
                                <div className="flex flex-col gap-2">
                                    <div className="text-xs font-bold uppercase text-slate-500 mb-1">Winning Copy</div>
                                    <div className="p-3 bg-green-50 border border-green-200 rounded-lg text-xs text-slate-700 whitespace-pre-wrap leading-relaxed max-h-64 overflow-hidden relative">
                                        {row[row.result!.winner]}
                                        <div className="absolute top-2 right-2">
                                            <Trophy className="w-4 h-4 text-green-600" />
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Detailed Voting Table */}
                        <div className="mt-8">
                            <h4 className="text-sm font-bold text-slate-800 mb-3 flex items-center gap-2">
                                <User className="w-4 h-4" />
                                Individual Persona Votes (100)
                            </h4>
                            <div className="bg-white border border-slate-200 rounded-lg overflow-hidden">
                                <table className="w-full text-xs">
                                    <thead className="bg-slate-50 border-b border-slate-200">
                                        <tr>
                                            <th className="p-2 text-left font-semibold text-slate-600 w-1/4">Persona</th>
                                            <th className="p-2 text-left font-semibold text-slate-600 w-1/4">Role</th>
                                            <th className="p-2 text-left font-semibold text-slate-600 w-1/6">Vote</th>
                                            <th className="p-2 text-left font-semibold text-slate-600">Rationale</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {row.result?.votes?.map((vote, vIdx) => (
                                            <tr key={vIdx} className="border-b border-slate-100 last:border-0 hover:bg-slate-50/50">
                                                <td className="p-2 font-medium text-slate-800">{vote.personaName}</td>
                                                <td className="p-2 text-slate-500">{vote.personaRole}</td>
                                                <td className="p-2">
                                                    <span 
                                                        className="px-1.5 py-0.5 rounded text-[10px] font-bold text-white whitespace-nowrap"
                                                        style={{ backgroundColor: colorMap[vote.votedFor] || '#94a3b8' }}
                                                    >
                                                        {vote.votedFor}
                                                    </span>
                                                </td>
                                                <td className="p-2 text-slate-600">
                                                    <div className="mb-1"><span className="text-green-600 font-semibold">Yes:</span> {vote.choiceRationale}</div>
                                                    {vote.rejectionRationale && <div><span className="text-red-500 font-semibold">No:</span> {vote.rejectionRationale}</div>}
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                );
            })}
        </div>

        {/* Footer */}
        <div className="mt-12 pt-6 border-t border-slate-200 text-center text-xs text-slate-400">
            Copy Critic Validation System • Powered by Gemini
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { ReportItem, MetaAnalysisResult, Job } from '../types';
import { analyzeSessionResults, analyzePdfReport } from '../services/geminiService';
import { Trophy, TrendingUp, Shield, Smile, Briefcase, PenTool, Upload, Loader2, ArrowLeft, FileText, CheckCircle, Download, Database, Clock } from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

interface Props {
  currentItems: ReportItem[];
  onBack: () => void;
  colorMap: Record<string, string>;
  savedJobs?: Job[];
}

const ICONS = {
  zap: TrendingUp,
  shield: Shield,
  smile: Smile,
  briefcase: Briefcase,
  pen: PenTool
};

export const InsightsDashboard: React.FC<Props> = ({ currentItems, onBack, colorMap, savedJobs = [] }) => {
  const [analysis, setAnalysis] = useState<MetaAnalysisResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [activeJobId, setActiveJobId] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const printRef = useRef<HTMLDivElement>(null);

  const handleAnalyzeItems = async (items: ReportItem[], jobId: string) => {
    setLoading(true);
    setError(null);
    setActiveJobId(jobId);
    try {
      const result = await analyzeSessionResults(items);
      setAnalysis(result);
    } catch (e: any) {
      setError(e.message || "Analysis failed");
    } finally {
      setLoading(false);
    }
  };

  const handlePdfUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);
    setActiveJobId('pdf');

    const reader = new FileReader();
    reader.onload = async (evt) => {
        try {
            const base64 = (evt.target?.result as string).split(',')[1];
            const result = await analyzePdfReport(base64);
            setAnalysis(result);
        } catch (e: any) {
            console.error("PDF Analysis Error:", e);
            setError(e.message || "Failed to analyze PDF. The file might be too large or complex for the current model.");
        } finally {
            setLoading(false);
            if (fileInputRef.current) {
                fileInputRef.current.value = '';
            }
        }
    };
    reader.readAsDataURL(file);
  };

  const handleDownloadPdf = async () => {
    if (!printRef.current) return;

    // Set explicit processing state for UI feedback
    const originalTitle = document.title;
    document.title = "Exporting PDF...";

    try {
        const element = printRef.current;
        await document.fonts.ready;

        const canvas = await html2canvas(element, {
            scale: 2,
            backgroundColor: '#ffffff',
            windowWidth: 800,
            useCORS: true,
            logging: false,
            x: 0,
            y: 0,
            scrollX: 0,
            scrollY: 0
        });

        if (canvas.width === 0 || canvas.height === 0) throw new Error("Canvas is empty");

        const imgData = canvas.toDataURL('image/png');
        const pdf = new jsPDF('p', 'mm', 'a4');
        const pdfWidth = pdf.internal.pageSize.getWidth();
        const pdfHeight = pdf.internal.pageSize.getHeight();
        const finalHeight = (canvas.height * pdfWidth) / canvas.width;

        let heightLeft = finalHeight;
        let position = 0;

        pdf.addImage(imgData, 'PNG', 0, position, pdfWidth, finalHeight);
        heightLeft -= pdfHeight;

        while (heightLeft >= 0) {
          position = heightLeft - finalHeight;
          pdf.addPage();
          pdf.addImage(imgData, 'PNG', 0, position, pdfWidth, finalHeight);
          heightLeft -= pdfHeight;
        }

        pdf.save('Meta_Analysis_Insights.pdf');
    } catch (e: any) {
        console.error("Export failed", e);
        alert(`Failed to generate PDF: ${e.message}`);
    } finally {
        document.title = originalTitle;
    }
  };

  if (loading) {
    return (
        <div className="min-h-[60vh] flex flex-col items-center justify-center animate-in fade-in">
            <div className="relative">
                <div className="absolute inset-0 bg-blue-500 blur-xl opacity-20 rounded-full animate-pulse"></div>
                <Loader2 className="w-16 h-16 text-blue-500 animate-spin relative z-10" />
            </div>
            <h2 className="mt-8 text-2xl font-bold text-white">Generating Meta-Analysis</h2>
            <p className="text-slate-400 mt-2">Our Senior Analyst AI is reading the rationales...</p>
        </div>
    );
  }

  if (analysis) {
    return (
        <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex items-center justify-between mb-6">
                <button onClick={() => setAnalysis(null)} className="flex items-center gap-2 text-slate-400 hover:text-white transition-colors">
                    <ArrowLeft className="w-4 h-4" /> Back to Selection
                </button>

                <button 
                    onClick={handleDownloadPdf}
                    className="flex items-center gap-2 bg-blue-600 hover:bg-blue-500 text-white px-4 py-2 rounded-lg font-bold text-sm transition-colors shadow-lg shadow-blue-500/20"
                >
                    <Download className="w-4 h-4" /> Download Report
                </button>
            </div>

            {/* Main Dashboard View */}
            <div className="flex flex-col md:flex-row gap-6 items-start md:items-center justify-between mb-10">
                <div>
                    <h1 className="text-3xl font-bold text-white mb-2">Validation Insights</h1>
                    <p className="text-slate-400 max-w-2xl">{analysis.executiveSummary}</p>
                </div>
                <div className="bg-yellow-500/10 border border-yellow-500/20 p-4 rounded-xl flex items-center gap-4">
                    <div className="bg-yellow-500/20 p-3 rounded-full">
                        <Trophy className="w-8 h-8 text-yellow-500" />
                    </div>
                    <div>
                        <div className="text-xs font-bold text-yellow-500 uppercase tracking-wider">Overall Champion</div>
                        <div className="text-2xl font-bold text-white">{analysis.overallChampion}</div>
                    </div>
                </div>
            </div>

            {/* Scenarios Grid */}
            <h3 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
                <TrendingUp className="w-5 h-5 text-blue-400" />
                Scenario Superlatives
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 mb-12">
                {analysis.scenarios?.map((scenario, idx) => {
                    const Icon = ICONS[scenario.icon] || Trophy;
                    return (
                        <div key={idx} className="bg-slate-800 border border-slate-700 p-5 rounded-xl hover:border-slate-600 transition-all">
                            <div className="flex items-start justify-between mb-3">
                                <div className="bg-slate-700/50 p-2 rounded-lg text-slate-300">
                                    <Icon className="w-5 h-5" />
                                </div>
                                <span className="text-xs font-bold px-2 py-1 rounded text-white" style={{ backgroundColor: colorMap[scenario.winner] || '#64748b' }}>
                                    {scenario.winner}
                                </span>
                            </div>
                            <h4 className="font-bold text-white mb-1">{scenario.title}</h4>
                            <p className="text-sm text-slate-400 leading-snug">{scenario.description}</p>
                        </div>
                    );
                })}
            </div>

            {/* Model Deep Dives */}
            <h3 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
                <FileText className="w-5 h-5 text-green-400" />
                Model Deep Dives
            </h3>
            <div className="space-y-6">
                {analysis.modelInsights?.map((model, idx) => (
                    <div key={idx} className="bg-slate-800/50 border border-slate-700 rounded-xl overflow-hidden">
                        <div className="p-4 bg-slate-800 border-b border-slate-700 flex items-center justify-between">
                            <h4 className="font-bold text-lg text-white flex items-center gap-2">
                                <div className="w-3 h-3 rounded-full" style={{ backgroundColor: colorMap[model.modelName] || '#64748b' }}></div>
                                {model.modelName}
                            </h4>
                            <div className="text-sm font-mono text-slate-400">Win Rate: <span className="text-white font-bold">{model.winRate}%</span></div>
                        </div>
                        <div className="p-6 grid grid-cols-1 md:grid-cols-3 gap-8">
                            <div>
                                <div className="text-xs font-bold text-green-400 uppercase mb-3 flex items-center gap-2">
                                    <CheckCircle className="w-4 h-4" /> Strengths
                                </div>
                                <ul className="space-y-2">
                                    {model.strengths?.map((s, i) => (
                                        <li key={i} className="text-sm text-slate-300 flex items-start gap-2">
                                            <span className="w-1 h-1 bg-green-500 rounded-full mt-1.5 shrink-0"></span>
                                            {s}
                                        </li>
                                    ))}
                                </ul>
                            </div>
                            <div>
                                <div className="text-xs font-bold text-red-400 uppercase mb-3 flex items-center gap-2">
                                    <Shield className="w-4 h-4" /> Weaknesses
                                </div>
                                <ul className="space-y-2">
                                    {model.weaknesses?.map((w, i) => (
                                        <li key={i} className="text-sm text-slate-300 flex items-start gap-2">
                                            <span className="w-1 h-1 bg-red-500 rounded-full mt-1.5 shrink-0"></span>
                                            {w}
                                        </li>
                                    ))}
                                </ul>
                            </div>
                            <div>
                                <div className="text-xs font-bold text-blue-400 uppercase mb-3 flex items-center gap-2">
                                    <Briefcase className="w-4 h-4" /> Best Use Cases
                                </div>
                                <div className="flex flex-wrap gap-2">
                                    {model.bestUseCases?.map((uc, i) => (
                                        <span key={i} className="text-xs bg-slate-900 border border-slate-700 text-slate-300 px-3 py-1.5 rounded-full">
                                            {uc}
                                        </span>
                                    ))}
                                </div>
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            {/* Hidden Print Container */}
            <div style={{ position: 'absolute', top: 0, left: '-10000px', width: '800px', zIndex: -50 }}>
                <div 
                    ref={printRef} 
                    className="min-h-screen bg-white text-slate-900 p-12 font-sans"
                    style={{ width: '800px' }}
                >
                     {/* Print Header */}
                    <div className="border-b-2 border-slate-900 pb-6 mb-10">
                        <div className="flex items-center gap-3 mb-2">
                            <div className="bg-blue-600 p-2 rounded-lg">
                                {/* Simple Logo SVG */}
                                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2">
                                <path d="M2 20h20M22 20V4a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2v16M12 12a3 3 0 1 0 0-6 3 3 0 0 0 0 6" />
                                </svg>
                            </div>
                            <h1 className="text-3xl font-bold text-slate-900">Validation Insights</h1>
                        </div>
                        <p className="text-slate-500 text-lg">Meta-Analysis Report</p>
                        <div className="mt-2 text-sm text-slate-400">Generated on {new Date().toLocaleDateString()}</div>
                    </div>

                    {/* Executive Summary */}
                    <div className="mb-10 p-6 bg-slate-50 rounded-xl border border-slate-100">
                        <h2 className="text-sm font-bold uppercase tracking-wider text-slate-500 mb-3">Executive Summary</h2>
                        <p className="text-lg font-medium text-slate-800 leading-relaxed">{analysis.executiveSummary}</p>
                    </div>

                    {/* Overall Champion */}
                    <div className="mb-12 flex items-center gap-6 p-6 border-l-4 border-yellow-500 bg-yellow-50 rounded-r-xl">
                        <div className="bg-yellow-100 p-4 rounded-full">
                             <Trophy className="w-10 h-10 text-yellow-600" />
                        </div>
                        <div>
                             <div className="text-sm font-bold text-yellow-700 uppercase">Overall Champion</div>
                             <div className="text-3xl font-bold text-slate-900">{analysis.overallChampion}</div>
                        </div>
                    </div>

                    {/* Scenario Table */}
                    <h3 className="text-xl font-bold text-slate-900 mb-6 flex items-center gap-2">
                        <TrendingUp className="w-5 h-5 text-blue-600" />
                        Scenario Superlatives
                    </h3>
                    <div className="grid grid-cols-2 gap-4 mb-12">
                         {analysis.scenarios?.map((s, i) => (
                             <div key={i} className="border border-slate-200 p-4 rounded-lg break-inside-avoid">
                                 <div className="flex justify-between items-start mb-2">
                                     <h4 className="font-bold text-slate-800">{s.title}</h4>
                                     <span className="text-xs px-2 py-1 rounded font-bold text-white" style={{ backgroundColor: colorMap[s.winner] || '#64748b' }}>
                                         {s.winner}
                                     </span>
                                 </div>
                                 <p className="text-sm text-slate-600">{s.description}</p>
                             </div>
                         ))}
                    </div>

                    {/* Model Breakdown */}
                    <h3 className="text-xl font-bold text-slate-900 mb-6 flex items-center gap-2">
                        <FileText className="w-5 h-5 text-green-600" />
                        Strategic Analysis
                    </h3>
                    <div className="space-y-8">
                        {analysis.modelInsights?.map((m, i) => (
                            <div key={i} className="border-t border-slate-200 pt-6 break-inside-avoid">
                                <div className="flex items-center justify-between mb-4">
                                     <h4 className="text-lg font-bold text-slate-900 flex items-center gap-2">
                                         <div className="w-3 h-3 rounded-full" style={{ backgroundColor: colorMap[m.modelName] || '#64748b' }}></div>
                                         {m.modelName}
                                     </h4>
                                     <span className="font-mono text-sm text-slate-500">Win Rate: {m.winRate}%</span>
                                </div>
                                <div className="grid grid-cols-3 gap-6">
                                    <div>
                                        <div className="text-xs font-bold text-green-600 uppercase mb-2">Strengths</div>
                                        <ul className="list-disc list-inside text-xs text-slate-600 space-y-1">
                                            {m.strengths?.map((s, idx) => <li key={idx}>{s}</li>)}
                                        </ul>
                                    </div>
                                    <div>
                                        <div className="text-xs font-bold text-red-500 uppercase mb-2">Weaknesses</div>
                                        <ul className="list-disc list-inside text-xs text-slate-600 space-y-1">
                                            {m.weaknesses?.map((w, idx) => <li key={idx}>{w}</li>)}
                                        </ul>
                                    </div>
                                    <div>
                                        <div className="text-xs font-bold text-blue-600 uppercase mb-2">Best For</div>
                                        <div className="flex flex-wrap gap-1">
                                            {m.bestUseCases?.map((u, idx) => (
                                                <span key={idx} className="bg-slate-100 text-slate-600 px-2 py-1 rounded text-xs border border-slate-200">{u}</span>
                                            ))}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>

                    <div className="mt-12 pt-6 border-t border-slate-200 text-center text-xs text-slate-400">
                        Generated by CopyCritic AI Validation Suite
                    </div>
                </div>
            </div>
        </div>
    );
  }

  // Initial Selection View
  return (
    <div className="w-full max-w-4xl mx-auto py-10 animate-in fade-in slide-in-from-bottom-8">
        <button onClick={onBack} className="mb-8 flex items-center gap-2 text-slate-400 hover:text-white transition-colors">
            <ArrowLeft className="w-4 h-4" /> Back to Testing
        </button>

        <div className="text-center mb-12">
            <h2 className="text-3xl font-bold text-white mb-3">Meta-Analysis Dashboard</h2>
            <p className="text-slate-400">Discover strategic insights across multiple test cases.</p>
        </div>

        {error && (
             <div className="mb-8 bg-red-500/10 border border-red-500/20 p-4 rounded-lg text-red-400 text-sm text-center">
                 {error}
             </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Option 1: Current Session */}
            <button 
                onClick={() => handleAnalyzeItems(currentItems, 'current')}
                disabled={currentItems.filter(i => i.status === 'done').length === 0}
                className="bg-slate-800 hover:bg-slate-750 border border-slate-700 hover:border-blue-500/50 rounded-2xl p-8 flex flex-col items-center text-center transition-all group disabled:opacity-50 disabled:cursor-not-allowed"
            >
                <div className="w-16 h-16 bg-blue-500/10 rounded-full flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                    <Trophy className="w-8 h-8 text-blue-500" />
                </div>
                <h3 className="text-xl font-bold text-white mb-2">Analyze Current Session</h3>
                <p className="text-sm text-slate-400 mb-6">
                    Generate insights from the {currentItems.filter(i => i.status === 'done').length} completed tests.
                </p>
                <div className="mt-auto px-6 py-2 bg-blue-600 group-hover:bg-blue-500 text-white rounded-lg font-bold text-sm">
                    Generate Report
                </div>
            </button>

            {/* Option 2: Upload PDF */}
            <div 
                onClick={() => fileInputRef.current?.click()}
                className="bg-slate-800 hover:bg-slate-750 border border-slate-700 hover:border-green-500/50 rounded-2xl p-8 flex flex-col items-center text-center transition-all cursor-pointer group"
            >
                <div className="w-16 h-16 bg-green-500/10 rounded-full flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                    <Upload className="w-8 h-8 text-green-500" />
                </div>
                <h3 className="text-xl font-bold text-white mb-2">Analyze Historical Report</h3>
                <p className="text-sm text-slate-400 mb-6">
                    Upload a previously generated PDF to extract insights.
                </p>
                <div className="mt-auto px-6 py-2 bg-green-600 group-hover:bg-green-500 text-white rounded-lg font-bold text-sm">
                    Upload PDF
                </div>
                <input 
                    type="file" 
                    ref={fileInputRef}
                    accept="application/pdf"
                    className="hidden"
                    onChange={handlePdfUpload}
                />
            </div>
        </div>

        {/* Option 3: Saved Jobs */}
        {savedJobs.length > 0 && (
            <div className="mt-12">
                <h3 className="text-xl font-bold text-white mb-4 flex items-center gap-2">
                    <Database className="w-5 h-5 text-purple-400" />
                    Saved Job History
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {savedJobs.map((job) => (
                        <div 
                            key={job.id}
                            onClick={() => handleAnalyzeItems(job.items, job.id)}
                            className="bg-slate-800 border border-slate-700 hover:border-purple-500/50 p-4 rounded-xl cursor-pointer transition-colors group"
                        >
                            <div className="flex items-center justify-between mb-2">
                                <span className="text-sm font-bold text-white">{job.name}</span>
                                <span className="text-xs text-purple-400 bg-purple-500/10 px-2 py-0.5 rounded">{job.items.filter(i => i.status === 'done').length} Tests</span>
                            </div>
                            <div className="flex items-center gap-2 text-xs text-slate-500">
                                <Clock className="w-3 h-3" />
                                {new Date(job.timestamp).toLocaleString()}
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { FileUpload } from './components/FileUpload';
import { TestReportCard } from './components/TestReportCard';
import { PersonaGrid } from './components/PersonaGrid';
import { PdfReport } from './components/PdfReport';
import { InsightsDashboard } from './components/InsightsDashboard';
import { generatePersonas, runVotingSession } from './services/geminiService';
import { ExcelRow, Persona, ReportItem, ProcessedRow, COLOR_PALETTE, Job } from './types';
import { Brain, Users, Play, Loader2, Download, Zap, RefreshCw, AlertTriangle, Tag, PieChart, Save, Database } from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

export default function App() {
  const [step, setStep] = useState<'upload' | 'recruit' | 'report' | 'insights'>('upload');
  const [previousStep, setPreviousStep] = useState<'upload' | 'recruit' | 'report'>('upload');
  const [items, setItems] = useState<ReportItem[]>([]);
  const [personas, setPersonas] = useState<Persona[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isRecruiting, setIsRecruiting] = useState(false);

  // Job History State
  const [savedJobs, setSavedJobs] = useState<Job[]>([]);

  // Dynamic Columns & Colors
  const [modelColumns, setModelColumns] = useState<string[]>([]);
  const [colorMap, setColorMap] = useState<Record<string, string>>({});

  const pdfReportRef = useRef<HTMLDivElement>(null);
  const reportContainerRef = useRef<HTMLDivElement>(null);

  // Load jobs from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem('copyCritic_jobs');
    if (saved) {
        try {
            setSavedJobs(JSON.parse(saved));
        } catch (e) {
            console.error("Failed to load saved jobs", e);
        }
    }
  }, []);

  // 1. Upload Handler
  const handleDataLoaded = (data: ExcelRow[]) => {
    if (data.length > 0) {
      // Dynamically detect model columns (exclude Test, Prompt, and any system keys)
      const firstRow = data[0];
      const cols = Object.keys(firstRow).filter(k => 
        k !== 'Test' && 
        k !== 'Prompt' && 
        k !== '__rowNum__' && 
        k !== 'id'
      );

      setModelColumns(cols);

      // Assign colors round-robin
      const newColors: Record<string, string> = {};
      cols.forEach((col, i) => {
        newColors[col] = COLOR_PALETTE[i % COLOR_PALETTE.length];
      });
      setColorMap(newColors);
    }

    const reportItems: ReportItem[] = data.map((row, i) => ({
      ...row,
      id: `test-${i}`,
      status: 'idle'
    }));
    setItems(reportItems);
    setStep('recruit');
  };

  // 2. Recruit Handler
  const handleRecruit = async () => {
    setIsRecruiting(true);
    await new Promise(r => setTimeout(r, 800));
    const p = await generatePersonas(false);
    setPersonas(p);
    setIsRecruiting(false);
    setStep('report');
  };

  // 3. Run All Handler
  const handleRunAll = async () => {
    setIsProcessing(true);

    const pendingIndices = items.map((item, index) => item.status !== 'done' ? index : -1).filter(i => i !== -1);
    const BATCH_SIZE = 1;

    for (let i = 0; i < pendingIndices.length; i += BATCH_SIZE) {
        const batchIndices = pendingIndices.slice(i, i + BATCH_SIZE);

        setItems(prev => {
            const next = [...prev];
            batchIndices.forEach(idx => {
                next[idx] = { ...next[idx], status: 'running', errorMessage: undefined };
            });
            return next;
        });

        await Promise.all(batchIndices.map(async (index) => {
            const item = items[index];

            // Construct dynamic candidates object
            const candidates: Record<string, string> = {};
            modelColumns.forEach(col => {
                candidates[col] = item[col] || "";
            });

            try {
                const analysis = await runVotingSession(item.Prompt, candidates, personas);

                setItems(prev => {
                    const next = [...prev];
                    next[index] = { ...next[index], status: 'done', analysis };
                    return next;
                });
            } catch (error: any) {
                console.error(`Error processing item ${index}`, error);
                setItems(prev => {
                    const next = [...prev];
                    next[index] = { 
                        ...next[index], 
                        status: 'error',
                        errorMessage: error.message || "Unknown error occurred"
                    };
                    return next;
                });
            }
        }));

        if (i + BATCH_SIZE < pendingIndices.length) {
            await new Promise(resolve => setTimeout(resolve, 500));
        }
    }

    setIsProcessing(false);
  };

  const handleSaveJob = () => {
    const jobName = prompt("Enter a name for this job run:", `Run ${new Date().toLocaleTimeString()}`);
    if (!jobName) return;

    const newJob: Job = {
        id: crypto.randomUUID(),
        timestamp: Date.now(),
        name: jobName,
        items,
        personas
    };

    const updatedJobs = [newJob, ...savedJobs];
    setSavedJobs(updatedJobs);
    localStorage.setItem('copyCritic_jobs', JSON.stringify(updatedJobs));
    alert("Job saved successfully!");
  };

  const handleExportPDF = async () => {
    if (!pdfReportRef.current) {
        alert("Report reference not found. Please try again.");
        return;
    }

    // Show a temporary loading state or toast if needed
    const originalTitle = document.title;
    document.title = "Generating PDF...";

    try {
        const element = pdfReportRef.current;

        // Ensure fonts are loaded before capture
        await document.fonts.ready;

        const canvas = await html2canvas(element, { 
            scale: 1, // Reduced to 1 to prevent "Incomplete or corrupt PNG file" on large reports
            backgroundColor: '#ffffff',
            windowWidth: 800,
            useCORS: true,
            logging: false,
            x: 0,
            y: 0,
            scrollX: 0,
            scrollY: 0
        });

        if (canvas.width === 0 || canvas.height === 0) {
            throw new Error("Canvas generated was empty. Please verify data.");
        }

        const imgData = canvas.toDataURL('image/png');

        // Validate image data
        if (imgData.length < 1000) {
             throw new Error("Generated image data is incomplete or corrupt. The report may be too large.");
        }

        const pdf = new jsPDF('p', 'mm', 'a4');
        const pdfWidth = pdf.internal.pageSize.getWidth();
        const pdfHeight = pdf.internal.pageSize.getHeight();
        const imgWidth = canvas.width;
        const imgHeight = canvas.height;
        const ratio = pdfWidth / imgWidth;
        const finalHeight = imgHeight * ratio;

        let heightLeft = finalHeight;
        let position = 0;

        pdf.addImage(imgData, 'PNG', 0, position, pdfWidth, finalHeight);
        heightLeft -= pdfHeight;

        while (heightLeft >= 0) {
          position = heightLeft - finalHeight;
          pdf.addPage();
          pdf.addImage(imgData, 'PNG', 0, position, pdfWidth, finalHeight);
          heightLeft -= pdfHeight;
        }
        pdf.save('CopyCritic_Report.pdf');
    } catch (e: any) {
        console.error(e);
        alert(`Export failed: ${e.message || 'Unknown error'}`);
    } finally {
        document.title = originalTitle;
    }
  };

  const completedCount = items.filter(i => i.status === 'done').length;

  const processedRows: ProcessedRow[] = items.map(item => ({
      ...item,
      id: item.id,
      status: item.status === 'done' ? 'completed' : item.status === 'idle' ? 'pending' : 'failed',
      result: item.analysis ? {
          winner: item.analysis.winner,
          counts: item.analysis.counts,
          votes: item.analysis.votes,
          reasoning: item.analysis.summary
      } : undefined
  }));

  const goToInsights = () => {
    if (step !== 'insights') {
        setPreviousStep(step);
        setStep('insights');
    }
  };

  const backFromInsights = () => {
    setStep(previousStep);
  };

  return (
    <div className="min-h-screen bg-slate-900 text-slate-100 font-sans pb-20">

      {/* Hidden PDF Render Target - Always rendered but hidden via absolute/z-index */}
      <PdfReport 
        rows={processedRows} 
        reportRef={pdfReportRef} 
        modelColumns={modelColumns}
        colorMap={colorMap}
      />

      {/* Header */}
      <header className="border-b border-slate-800 bg-slate-900/90 backdrop-blur sticky top-0 z-50">
        <div className="max-w-4xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2 font-bold text-xl cursor-pointer" onClick={() => step === 'insights' ? backFromInsights() : null}>
            <Brain className="text-blue-500" />
            CopyCritic
            <span className="text-[10px] font-medium bg-green-500/10 text-green-400 px-2 py-0.5 rounded-full border border-green-500/20 flex items-center gap-1">
              <Tag className="w-3 h-3" />
              v1.5.1
            </span>
          </div>
          <div className="flex items-center gap-4">
            <div className="text-sm text-slate-500">
               {personas.length > 0 ? `${personas.length} Personas Active` : ''}
            </div>
            {step !== 'insights' && (
                <button 
                    onClick={goToInsights}
                    className="text-xs bg-slate-800 hover:bg-slate-700 text-blue-400 border border-slate-700 px-3 py-1.5 rounded-lg font-medium transition-colors flex items-center gap-2"
                >
                    <PieChart className="w-3 h-3" />
                    Meta Analysis
                </button>
            )}
          </div>
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-6 py-10">

        {step === 'insights' ? (
            <InsightsDashboard 
                currentItems={items} 
                onBack={backFromInsights}
                colorMap={colorMap}
                savedJobs={savedJobs}
            />
        ) : (
            <>
                {step === 'upload' && (
                  <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                    <h1 className="text-3xl font-bold text-center mb-4">Upload Validation Data</h1>
                    <p className="text-center text-slate-400 mb-10">Upload your Excel sheet containing tests and model outputs.</p>
                    <FileUpload onDataLoaded={handleDataLoaded} />
                  </div>
                )}

                {step === 'recruit' && (
                  <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 text-center py-10">
                    <div className="inline-flex p-6 bg-blue-500/10 rounded-full mb-6">
                      <Users className="w-12 h-12 text-blue-500" />
                    </div>
                    <h2 className="text-2xl font-bold mb-4">Recruit Synthetic Panel</h2>
                    <p className="text-slate-400 mb-8 max-w-md mx-auto">
                      We need to instantiate 100 unique marketing personas to judge your {modelColumns.length} models: <br/>
                      <span className="text-blue-400 font-mono text-xs">{modelColumns.join(', ')}</span>
                    </p>
                    <button 
                      onClick={handleRecruit}
                      disabled={isRecruiting}
                      className="bg-blue-600 hover:bg-blue-500 text-white px-8 py-3 rounded-xl font-bold transition-all flex items-center gap-2 mx-auto"
                    >
                      {isRecruiting ? <Loader2 className="animate-spin" /> : <Users className="w-5 h-5" />}
                      Recruit 100 Personas
                    </button>
                  </div>
                )}

                {step === 'report' && (
                  <div className="space-y-8 animate-in fade-in duration-500">

                    <PersonaGrid personas={personas} isGenerating={isRecruiting} />

                    {items.length === 0 ? (
                        <div className="bg-slate-800 rounded-xl border border-slate-700 p-12 text-center animate-in fade-in zoom-in-95">
                            <div className="w-16 h-16 bg-slate-700/50 rounded-full flex items-center justify-center mx-auto mb-4">
                                <RefreshCw className="w-8 h-8 text-slate-400" />
                            </div>
                            <h3 className="text-xl font-bold text-white mb-2">No Test Cases Loaded</h3>
                            <button onClick={() => setStep('upload')} className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2.5 rounded-lg font-bold transition-colors">
                                Upload Different File
                            </button>
                        </div>
                    ) : (
                        <>
                            <div className="bg-slate-800 p-4 rounded-xl border border-slate-700 flex items-center justify-between sticky top-20 z-40 shadow-xl">
                              <div className="flex items-center gap-4">
                                <div className="text-sm text-slate-400">
                                  <span className="text-white font-bold">{completedCount}</span> / {items.length} Evaluated
                                </div>
                                {isProcessing && (
                                    <div className="text-xs text-blue-400 animate-pulse flex items-center gap-1">
                                        <Zap className="w-3 h-3" />
                                        Processing...
                                    </div>
                                )}
                              </div>

                              <div className="flex gap-3">
                                 {completedCount > 0 && !isProcessing && (
                                     <button 
                                        onClick={handleSaveJob}
                                        className="p-2 hover:bg-slate-700 rounded-lg text-slate-400 hover:text-white" 
                                        title="Save Job to History"
                                    >
                                        <Save className="w-5 h-5" />
                                    </button>
                                 )}
                                 {completedCount > 0 && (
                                     <button onClick={handleExportPDF} className="p-2 hover:bg-slate-700 rounded-lg text-slate-400 hover:text-white" title="Export PDF">
                                         <Download className="w-5 h-5" />
                                     </button>
                                 )}
                                 {completedCount < items.length && (
                                    <button 
                                        onClick={handleRunAll}
                                        disabled={isProcessing}
                                        className="bg-green-600 hover:bg-green-500 text-white px-6 py-2 rounded-lg font-bold text-sm flex items-center gap-2 transition-all"
                                    >
                                        {isProcessing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Play className="w-4 h-4 fill-current" />}
                                        {items.some(i => i.status !== 'done') && completedCount > 0 ? "Resume Tests" : "Run All Tests"}
                                    </button>
                                 )}
                              </div>
                            </div>

                            <div className="space-y-8" ref={reportContainerRef}>
                              {items.map((item) => (
                                <div key={item.id}>
                                    {item.status === 'idle' ? (
                                         <div className="bg-slate-800/30 border border-slate-800 p-6 rounded-xl flex items-center justify-between opacity-50">
                                             <div>
                                                 <div className="text-xs font-bold text-slate-600 uppercase">Pending Test</div>
                                                 <div className="text-slate-400">{item.Test}</div>
                                             </div>
                                             <div className="h-2 w-2 bg-slate-700 rounded-full"></div>
                                         </div>
                                    ) : item.status === 'running' ? (
                                        <div className="bg-slate-800 border border-blue-500/30 p-8 rounded-xl flex flex-col items-center justify-center text-center animate-pulse">
                                            <Loader2 className="w-8 h-8 text-blue-500 animate-spin mb-4" />
                                            <h3 className="text-lg font-bold text-white mb-1">Panel is Voting...</h3>
                                            <p className="text-slate-400 text-sm">100 personas reading prompt "{item.Prompt.substring(0, 30)}..."</p>
                                        </div>
                                    ) : item.status === 'error' ? (
                                        <div className="bg-red-900/10 border border-red-500/30 p-6 rounded-xl flex flex-col items-center justify-center text-center">
                                            <AlertTriangle className="w-8 h-8 text-red-500 mb-2" />
                                            <h3 className="text-lg font-bold text-red-400 mb-1">Analysis Failed</h3>
                                            <p className="text-red-200/60 text-sm mb-4 max-w-lg">{item.errorMessage}</p>
                                        </div>
                                    ) : (
                                        <TestReportCard 
                                            item={item} 
                                            modelColumns={modelColumns} 
                                            colorMap={colorMap} 
                                        />
                                    )}
                                </div>
                              ))}
                            </div>
                        </>
                    )}
                  </div>
                )}
            </>
        )}
      </main>
    </div>
  );
}

import React, { useState, useRef } from 'react';
import { ReportItem, MetaAnalysisResult, Job } from '../types';
import { analyzeSessionResults, analyzePdfReport } from '../services/geminiService';
import { Trophy, TrendingUp, Shield, Smile, Briefcase, PenTool, Upload, Loader2, ArrowLeft, FileText, CheckCircle, Download, Database, Clock } from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

interface Props {
  currentItems: ReportItem[];
  onBack: () => void;
  colorMap: Record<string, string>;
  savedJobs?: Job[];
}

const ICONS = {
  zap: TrendingUp,
  shield: Shield,
  smile: Smile,
  briefcase: Briefcase,
  pen: PenTool
};

export const InsightsDashboard: React.FC<Props> = ({ currentItems, onBack, colorMap, savedJobs = [] }) => {
  const [analysis, setAnalysis] = useState<MetaAnalysisResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [activeJobId, setActiveJobId] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const printRef = useRef<HTMLDivElement>(null);

  const handleAnalyzeItems = async (items: ReportItem[], jobId: string) => {
    setLoading(true);
    setError(null);
    setActiveJobId(jobId);
    try {
      const result = await analyzeSessionResults(items);
      setAnalysis(result);
    } catch (e: any) {
      setError(e.message || "Analysis failed");
    } finally {
      setLoading(false);
    }
  };

  const handlePdfUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);
    setActiveJobId('pdf');

    const reader = new FileReader();
    reader.onload = async (evt) => {
        try {
            const base64 = (evt.target?.result as string).split(',')[1];
            const result = await analyzePdfReport(base64);
            setAnalysis(result);
        } catch (e: any) {
            console.error("PDF Analysis Error:", e);
            setError(e.message || "Failed to analyze PDF. The file might be too large or complex for the current model.");
        } finally {
            setLoading(false);
            if (fileInputRef.current) {
                fileInputRef.current.value = '';
            }
        }
    };
    reader.readAsDataURL(file);
  };

  const handleDownloadPdf = async () => {
    if (!printRef.current) return;

    // Set explicit processing state for UI feedback
    const originalTitle = document.title;
    document.title = "Exporting PDF...";

    try {
        const element = printRef.current;
        await document.fonts.ready;

        const canvas = await html2canvas(element, {
            scale: 1, // Reduced scale to 1 to minimize image size and prevent errors
            backgroundColor: '#ffffff',
            windowWidth: 800,
            useCORS: true,
            logging: false,
            x: 0,
            y: 0,
            scrollX: 0,
            scrollY: 0
        });

        if (canvas.width === 0 || canvas.height === 0) throw new Error("Canvas is empty");

        const imgData = canvas.toDataURL('image/png');

        // Validate
        if (imgData.length < 1000) {
            throw new Error("Generated PDF image data is corrupt/empty.");
        }

        const pdf = new jsPDF('p', 'mm', 'a4');
        const pdfWidth = pdf.internal.pageSize.getWidth();
        const pdfHeight = pdf.internal.pageSize.getHeight();
        const finalHeight = (canvas.height * pdfWidth) / canvas.width;

        let heightLeft = finalHeight;
        let position = 0;

        pdf.addImage(imgData, 'PNG', 0, position, pdfWidth, finalHeight);
        heightLeft -= pdfHeight;

        while (heightLeft >= 0) {
          position = heightLeft - finalHeight;
          pdf.addPage();
          pdf.addImage(imgData, 'PNG', 0, position, pdfWidth, finalHeight);
          heightLeft -= pdfHeight;
        }

        pdf.save('Meta_Analysis_Insights.pdf');
    } catch (e: any) {
        console.error("Export failed", e);
        alert(`Failed to generate PDF: ${e.message}`);
    } finally {
        document.title = originalTitle;
    }
  };

  if (loading) {
    return (
        <div className="min-h-[60vh] flex flex-col items-center justify-center animate-in fade-in">
            <div className="relative">
                <div className="absolute inset-0 bg-blue-500 blur-xl opacity-20 rounded-full animate-pulse"></div>
                <Loader2 className="w-16 h-16 text-blue-500 animate-spin relative z-10" />
