import { GoogleGenAI, Type, HarmCategory, HarmBlockThreshold } from "@google/genai";
import { Persona, AnalysisResult, Vote, MetaAnalysisResult, ReportItem } from '../types';
import { getStaticPersonas } from './staticData';

const getAiClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY not set");
  return new GoogleGenAI({ apiKey });
};

// Helper for timeout
const timeoutPromise = (ms: number) => new Promise((_, reject) => 
    setTimeout(() => reject(new Error(`Request timed out after ${ms/1000} seconds`)), ms)
);

// Helper for retry
async function fetchWithRetry<T>(fn: () => Promise<T>, retries = 2, delay = 1000): Promise<T> {
  try {
    return await fn();
  } catch (error) {
    if (retries > 0) {
      console.warn(`Batch failed, retrying in ${delay}ms...`, error);
      await new Promise(res => setTimeout(res, delay));
      return fetchWithRetry(fn, retries - 1, delay * 2);
    }
    throw error;
  }
}

// Helper to strip markdown code blocks
function cleanJson(text: string): string {
  if (!text) return "{}";
  let cleaned = text.trim();
  if (cleaned.startsWith("```json")) {
    cleaned = cleaned.replace(/^```json/, "").replace(/```$/, "");
  } else if (cleaned.startsWith("```")) {
    cleaned = cleaned.replace(/^```/, "").replace(/```$/, "");
  }
  return cleaned;
}

// Helper for concurrency control
async function pMap<T, R>(
    array: T[], 
    mapper: (item: T, index: number) => Promise<R>, 
    concurrency: number
): Promise<R[]> {
    const results = new Array<R>(array.length);
    let index = 0;
    const next = async (): Promise<void> => {
        if (index >= array.length) return;
        const i = index++;
        try {
            results[i] = await mapper(array[i], i);
        } catch (e) {
            throw e; 
        }
        await next();
    };
    const workers = [];
    for (let i = 0; i < concurrency && i < array.length; i++) {
        workers.push(next());
    }
    await Promise.all(workers);
    return results;
}

// 1. GENERATE PERSONAS
export const generatePersonas = async (useLiveAi: boolean = false): Promise<Persona[]> => {
  return getStaticPersonas();
};

// 2. RUN VOTING SESSION
export const runVotingSession = async (
  promptText: string,
  candidates: Record<string, string>,
  personas: Persona[]
): Promise<AnalysisResult> => {
  const ai = getAiClient();
  const modelNames = Object.keys(candidates);
  const LETTERS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";

  // Dynamic Mapping
  const ID_MAP: Record<string, string> = {};
  const REVERSE_MAP: Record<string, string> = {};

  modelNames.forEach((name, index) => {
    const letter = LETTERS[index] || `M${index}`;
    ID_MAP[letter] = name;
    REVERSE_MAP[name] = letter;
  });

  let candidateText = "";
  for (const [key, val] of Object.entries(candidates)) {
    const safeVal = val || "[No content generated]";
    candidateText += `MODEL ${REVERSE_MAP[key]}: \n${safeVal}\n\n`;
  }

  // --- BATCHING STRATEGY ---
  const BATCH_SIZE = 10;
  const personaBatches = [];
  for (let i = 0; i < personas.length; i += BATCH_SIZE) {
    personaBatches.push(personas.slice(i, i + BATCH_SIZE));
  }

  try {
    const results = await pMap(personaBatches, async (batchPersonas, batchIndex) => {
        const globalStartIndex = batchIndex * BATCH_SIZE;

        const personaList = batchPersonas.map((p, i) => 
            `#${i} ${p.name} (${p.role}): ${p.bias}`
        ).join('\n');

        const availableOptions = modelNames.map(m => REVERSE_MAP[m]).join('|');

        const systemInstruction = `
            You are simulating a voting panel of marketing personas.
            Task: Read the User Prompt and the Model Outputs (${availableOptions}).

            CONTEXT:
            The Model Outputs contain distinct creative elements: **Headline**, **Body Copy**, **On-Image Text**, and **CTA**.

            INSTRUCTIONS:
            1. **Holistic Evaluation**: Evaluate the synergy of the creative unit. 
               - **Flexibility**: If a model is missing one element (e.g. no CTA or no Image Text), do NOT penalize it if the other ~3 elements are strong. Judge the holistic quality of what is provided.
            2. **Persona Bias**: Analyze based on your specific persona bias.
            3. **Decision**: Decide which model constructed the best overall ad unit for EACH persona (#0 to #${batchPersonas.length - 1}).
            4. **Rationale**:
               - **choice_reason**: Crisp reason why this unit won (max 15 words).
               - **rejection_reason**: Crisp reason why the LOSERS failed (max 15 words). **IMPORTANT**: Refer to losing models by NAME (e.g. from [${availableOptions}]) if the critique is specific to them. Use "Others" only if the critique applies to all losers.

            OUTPUT FORMAT:
            Return ONLY a JSON object.
            keys: "summary" (string), "votes" (array).
            votes item: { 
                "i": number (0-${batchPersonas.length - 1}), 
                "c": "${availableOptions}", 
                "choice_reason": "string",
                "rejection_reason": "string"
            }
        `;

        const userPrompt = `
            PROMPT: "${promptText}"

            --- CANDIDATES ---
            ${candidateText}

            --- JURY (Batch ${batchIndex + 1}) ---
            ${personaList}
        `;

        return fetchWithRetry(async () => {
            const response: any = await Promise.race([
                ai.models.generateContent({
                  model: 'gemini-3-pro-preview',
                  config: {
                    systemInstruction: systemInstruction,
                    safetySettings: [
                      { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_NONE },
                      { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_NONE },
                      { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_NONE },
                      { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_NONE },
                    ],
                    responseMimeType: 'application/json',
                    responseSchema: {
                      type: Type.OBJECT,
                      properties: {
                        summary: { type: Type.STRING },
                        votes: {
                          type: Type.ARRAY,
                          items: {
                            type: Type.OBJECT,
                            properties: {
                              i: { type: Type.INTEGER },
                              c: { type: Type.STRING },
                              choice_reason: { type: Type.STRING },
                              rejection_reason: { type: Type.STRING }
                            },
                            required: ["i", "c", "choice_reason", "rejection_reason"]
                          }
                        }
                      }
                    }
                  },
                  contents: userPrompt
                }),
                timeoutPromise(60000) 
            ]);

            if (!response.text) {
                if (response.promptFeedback?.blockReason) {
                    throw new Error(`Blocked: ${response.promptFeedback.blockReason}`);
                }
                throw new Error("Empty response from AI model");
            }

            let json;
            try {
                json = JSON.parse(cleanJson(response.text));
            } catch (e) {
                console.error("JSON Parse Error", response.text);
                throw new Error("Invalid JSON response");
            }

            // Map votes back using the dynamic ID_MAP
            const mappedVotes = (json.votes || []).map((v: any) => ({
                personaIndex: (v.i !== undefined ? v.i : -1) + globalStartIndex,
                choice: v.c || REVERSE_MAP[modelNames[0]], 
                choiceRationale: v.choice_reason || "Good fit",
                rejectionRationale: v.rejection_reason || "Others were worse"
            }));

            return {
                votes: mappedVotes,
                summary: json.summary || ""
            };
        }, 2, 2000); 
    }, 3); 

    // --- AGGREGATION ---
    const allVotes: any[] = results.flatMap(r => r.votes);
    const summary = results[0]?.summary || "Analysis completed.";

    const counts: Record<string, number> = {};
    modelNames.forEach(m => counts[m] = 0);

    const finalVotes: Vote[] = [];

    allVotes.forEach((v: any) => {
      let choiceChar = v.choice?.toString().toUpperCase().trim() || '';
      // Extract just the letter if model hallucinates extra text
      const match = choiceChar.match(/^[A-Z]/); 
      if (match) choiceChar = match[0];

      const modelKey = ID_MAP[choiceChar];

      if (modelKey && personas[v.personaIndex]) {
        counts[modelKey] = (counts[modelKey] || 0) + 1;
        finalVotes.push({
          personaName: personas[v.personaIndex].name,
          personaRole: personas[v.personaIndex].role,
          votedFor: modelKey,
          choiceRationale: v.choiceRationale,
          rejectionRationale: v.rejectionRationale
        });
      }
    });

    let winner: string = modelNames[0];
    let max = -1;
    for (const m of modelNames) {
      if (counts[m] > max) {
        max = counts[m];
        winner = m;
      }
    }

    return { winner, counts, votes: finalVotes, summary };

  } catch (e: any) {
    console.error("Evaluation failed", e);
    throw new Error(e.message || "Error during voting session");
  }
};

// 3. META ANALYSIS (From Session Data)
export const analyzeSessionResults = async (items: ReportItem[]): Promise<MetaAnalysisResult> => {
    const ai = getAiClient();
    const completedItems = items.filter(i => i.status === 'done' && i.analysis);

    if (completedItems.length === 0) throw new Error("No completed tests to analyze");

    // Aggregate rich data for the analyst
    const summaryData = completedItems.map((item, idx) => {
        const votes = item.analysis?.votes || [];

        // Structure: Group rationales by model
        const modelFeedback: Record<string, { likes: string[], voteCount: number }> = {};
        const rejectionFeedback: string[] = [];

        // Initialize counts
        Object.keys(item.analysis?.counts || {}).forEach(m => {
            modelFeedback[m] = { likes: [], voteCount: item.analysis?.counts[m] || 0 };
        });

        votes.forEach(v => {
            // Collect why they chose this model
            if (modelFeedback[v.votedFor]) {
                modelFeedback[v.votedFor].likes.push(v.choiceRationale);
            }
            // Collect general rejection feedback (applies to non-chosen models)
            if (v.rejectionRationale) {
                rejectionFeedback.push(v.rejectionRationale);
            }
        });

        // Sample to fit in context window (take 5 distinct reasons per model)
        const sampledFeedback: Record<string, any> = {};
        Object.keys(modelFeedback).forEach(m => {
            const uniqueLikes = Array.from(new Set(modelFeedback[m].likes));
            sampledFeedback[m] = {
                votes: modelFeedback[m].voteCount,
                top_reasons_for_choosing: uniqueLikes.slice(0, 5)
            };
        });

        // Sample rejection feedback
        const uniqueRejections = Array.from(new Set(rejectionFeedback));

        return {
            test_id: idx,
            test_topic: item.Test,
            prompt: item.Prompt.substring(0, 150),
            winner: item.analysis?.winner,
            model_performance: sampledFeedback,
            general_criticism_of_losers: uniqueRejections.slice(0, 8)
        };
    });

    const systemInstruction = `
        You are a Senior Marketing Analyst. 
        Your job is to review a series of A/B tests between different AI models and provide high-level strategic insights.

        The tested content explicitly includes **Headlines**, **Body Copy**, **On-Image Text**, and **CTAs**.

        Analyze the provided JSON data. For each test, you have:
        - "model_performance": containing vote counts and specific reasons ("top_reasons_for_choosing") why personas liked a model.
        - "general_criticism_of_losers": reasons why personas rejected the other options.

        Task:
        1. Identify the Overall Champion (highest total win rate).
        2. Assign Specific "Awards" (e.g. Best Headline Writer, Strongest Visual Flow, Best CTA, Best for Corporate, Safest Choice) based on the patterns in the feedback.
        3. Create a Deep Dive for EACH model. Use the "top_reasons_for_choosing" to identify STRENGTHS (e.g., "Great headlines"). Use "general_criticism_of_losers" to identify WEAKNESSES (e.g., "Weak CTAs", "Body copy disconnected from visual").
        4. Define "Best Use Cases" for each model based on where it succeeded.
    `;

    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview', // Using Pro for complex reasoning over dataset
        config: {
            systemInstruction,
            responseMimeType: 'application/json',
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    overallChampion: { type: Type.STRING },
                    executiveSummary: { type: Type.STRING },
                    scenarios: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                title: { type: Type.STRING },
                                winner: { type: Type.STRING },
                                description: { type: Type.STRING },
                                icon: { type: Type.STRING, enum: ['zap', 'shield', 'smile', 'briefcase', 'pen'] }
                            }
                        }
                    },
                    modelInsights: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                modelName: { type: Type.STRING },
                                strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
                                weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
                                bestUseCases: { type: Type.ARRAY, items: { type: Type.STRING } },
                                winRate: { type: Type.NUMBER, description: "Percentage 0-100" }
                            }
                        }
                    }
                }
            }
        },
        contents: JSON.stringify(summaryData)
    });

    if (!response.text) throw new Error("No analysis generated");
    return JSON.parse(cleanJson(response.text));
};

// 4. META ANALYSIS (From PDF)
export const analyzePdfReport = async (base64Pdf: string): Promise<MetaAnalysisResult> => {
    const ai = getAiClient();

    // The PDF is generated via html2canvas, so it consists of screenshots/images of tables and charts.
    // The model needs to visually parse these images.
    const systemInstruction = `
        You are a Senior Marketing Analyst. 
        Read the provided PDF report. 

        IMPORTANT: This PDF might contain MULTIPLE concatenated reports from different sessions.
        You must AGGREGATE the data across all pages and sections found in the document to provide a single, unified analysis.

        Aggregation Rules:
        1. If multiple Executive Summaries exist, sum the vote counts for each model.
        2. Identify the Overall Champion based on the combined win rate across ALL tests in the PDF.
        3. Identify trends, strengths, and weaknesses that persist across the entire dataset.

        Extract and Analyze:
        1. The Overall Champion (which model won the most tests across the entire file?).
        2. Specific "Awards" (Best for Humor, Professionalism, etc) based on the test prompts/results you see.
        3. Model Deep Dives (Strengths/Weaknesses) derived from the visuals of the rationale text.

        Return ONLY valid JSON with the following structure:
        {
          "overallChampion": "string",
          "executiveSummary": "string",
          "scenarios": [{ "title": "string", "winner": "string", "description": "string", "icon": "zap" | "shield" | "smile" | "briefcase" | "pen" }],
          "modelInsights": [{ "modelName": "string", "strengths": ["string"], "weaknesses": ["string"], "bestUseCases": ["string"], "winRate": number }]
        }
    `;

    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        config: {
            systemInstruction,
            responseMimeType: 'application/json',
            // NOTE: We do NOT use responseSchema here intentionally. 
            // When dealing with complex visual parsing from PDFs in the Preview model, 
            // strict schema validation can sometimes cause the model to fail or reject valid visual interpretations.
            // We rely on the system instruction and JSON mode to get the correct structure.
        },
        contents: {
            parts: [
                { inlineData: { mimeType: 'application/pdf', data: base64Pdf } },
                { text: "Analyze this visual report (which may contain multiple merged reports) and provide the structured JSON insights." }
            ]
        }
    });

    if (!response.text) throw new Error("No analysis generated");

    try {
        return JSON.parse(cleanJson(response.text));
    } catch (e) {
        console.error("Failed to parse PDF analysis JSON", response.text);
        throw new Error("The AI analyzed the PDF but returned invalid JSON.");
    }
};

import React, { useState, useRef } from 'react';
import { ReportItem, MetaAnalysisResult, Job } from '../types';
import { analyzeSessionResults, analyzePdfReport } from '../services/geminiService';
import { Trophy, TrendingUp, Shield, Smile, Briefcase, PenTool, Upload, Loader2, ArrowLeft, FileText, CheckCircle, Download, Database, Clock } from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

interface Props {
  currentItems: ReportItem[];
  onBack: () => void;
  colorMap: Record<string, string>;
  savedJobs?: Job[];
}

const ICONS = {
  zap: TrendingUp,
  shield: Shield,
  smile: Smile,
  briefcase: Briefcase,
  pen: PenTool
};

export const InsightsDashboard: React.FC<Props> = ({ currentItems, onBack, colorMap, savedJobs = [] }) => {
  const [analysis, setAnalysis] = useState<MetaAnalysisResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [activeJobId, setActiveJobId] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const printRef = useRef<HTMLDivElement>(null);

  const handleAnalyzeItems = async (items: ReportItem[], jobId: string) => {
    setLoading(true);
    setError(null);
    setActiveJobId(jobId);
    try {
      const result = await analyzeSessionResults(items);
      setAnalysis(result);
    } catch (e: any) {
      setError(e.message || "Analysis failed");
    } finally {
      setLoading(false);
    }
  };

  const handlePdfUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);
    setActiveJobId('pdf');

    const reader = new FileReader();
    reader.onload = async (evt) => {
        try {
            const base64 = (evt.target?.result as string).split(',')[1];
            const result = await analyzePdfReport(base64);
            setAnalysis(result);
        } catch (e: any) {
            console.error("PDF Analysis Error:", e);
            setError(e.message || "Failed to analyze PDF. The file might be too large or complex for the current model.");
        } finally {
            setLoading(false);
            if (fileInputRef.current) {
                fileInputRef.current.value = '';
            }
        }
    };
    reader.readAsDataURL(file);
  };

  const handleDownloadPdf = async () => {
    if (!printRef.current) return;

    // Set explicit processing state for UI feedback
    const originalTitle = document.title;
    document.title = "Exporting PDF...";

    try {
        const element = printRef.current;
        await document.fonts.ready;

        const canvas = await html2canvas(element, {
            scale: 1, // Reduced scale to 1 to minimize image size and prevent errors
            backgroundColor: '#ffffff',
            windowWidth: 800,
            useCORS: true,
            logging: false,
            x: 0,
            y: 0,
            scrollX: 0,
            scrollY: 0
        });

        if (canvas.width === 0 || canvas.height === 0) throw new Error("Canvas is empty");

        const imgData = canvas.toDataURL('image/png');

        // Validate
        if (imgData.length < 1000) {
            throw new Error("Generated PDF image data is corrupt/empty.");
        }

        const pdf = new jsPDF('p', 'mm', 'a4');
        const pdfWidth = pdf.internal.pageSize.getWidth();
        const pdfHeight = pdf.internal.pageSize.getHeight();
        const finalHeight = (canvas.height * pdfWidth) / canvas.width;

        let heightLeft = finalHeight;
        let position = 0;

        pdf.addImage(imgData, 'PNG', 0, position, pdfWidth, finalHeight);
        heightLeft -= pdfHeight;

        while (heightLeft >= 0) {
          position = heightLeft - finalHeight;
          pdf.addPage();
          pdf.addImage(imgData, 'PNG', 0, position, pdfWidth, finalHeight);
          heightLeft -= pdfHeight;
        }

        pdf.save('Meta_Analysis_Insights.pdf');
    } catch (e: any) {
        console.error("Export failed", e);
        alert(`Failed to generate PDF: ${e.message}`);
    } finally {
        document.title = originalTitle;
    }
  };

